quests[14131] = { id = 14131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Pick-me-up", description = "Azuregos... Azuregos. Azy? The dragon? We're friends, definitely! Taught me to speak. Said he liked my hue... kinda colorist, eh?\n\nDon't remember where he went. Mmm... maybe something to help my memory?\n\nI plant Kawphi plants all over the beach. They like sand. Kinda weird.\n\nCould you go collect some?", sourceObjective = "Collect 10 Kawphi Beans from the plants in the Ruins of Arkkoran.", progress = "So tired, it's hard to concentrate.", completion = "Beautiful beans! They smell absolutely delicious, don't they?", sourceObjectiveStatus = "unverified-source-field" }
quests[14132] = { id = 14132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Just Rude!", description = "I'd share if they asked. They just go clickity-claking up my kawphi plants. So rude! You should teach them a lesson.\n\nDumb Makrinni.", sourceObjective = "Kill 10 Makrinni in the Ruins of Arkkoran.", completion = "Too mean? Naw, not too mean. They deserved it.\n\nI don't gum up their plants. Not ever.", sourceObjectiveStatus = "unverified-source-field" }
quests[14134] = { id = 14134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captain's Logs", description = "Now that you've got that thing under control, let's gather up the lumber I was supposed to be collecting. Otherwise these orcs are going to build a catapult out of ME!\n\nFresh lumber should be stockpiled all around the area. Use the shredder to collect all you can.", sourceObjective = "Use the Reprogrammed Shredder to collect 6 piles of Azshara Lumber. If you lose your shredder, another can be attacked and reprogrammed.", progress = "How's the wood processing going? You should see what that thing does to broccoli!", completion = "Great! You've loaded the shredder to capacity. You're getting pretty handy with that thing...", sourceObjectiveStatus = "unverified-source-field" }
quests[14135] = { id = 14135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up a Tree", description = "Hold still a second, I'm going to bring your main buzzsaw controls online.\n\nNight elven snipers from Talrendis have been hiding in the trees, taking potshots at my workers. I want you to take care of those snipers... by first taking care of those trees. Look for Azshara saplings east of the main gates. Your shredder will know what to do. Chop to it!", sourceObjective = "Use the shredder's buzzsaw to cut down Azshara Saplings, and kill 9 Talrendis Snipers as they emerge.", completion = "Great work, {name}! That's how we took care of business back on Kezan.", sourceObjectiveStatus = "unverified-source-field" }
quests[14136] = { id = 14136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue at Sea", description = "The Kvaldir have set up camp at Hrothgar's Landing, the small island to the North.  We sent Captain Aerthas Firehawk to the area, but they ran into a Kvaldir Raiding party heading to the Tournament Grounds!  The Firehawk is now under attack by the raiders and is vastly outnumbered. Get out there and show those Kvaldir why attacking the Sunreavers is a poor plan indeed. \n\nThe Firehawk is between Hrothgar's Landing to the north and the Tournament Grounds, on the western side of The Sea Reaver's Run.", sourceObjective = "Girana the Blooded at the Argent Tournament Grounds would like you to kill 8 Kvaldir Berserkers and 3 Kvaldir Harpooners aboard The Firehawk.", completion = "Great job, Champion.  The fight continues, but now the Kvaldir know that we do not tolerate such attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[14138] = { id = 14138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Care of Business", description = "With all of the troubles down in the Kaja'mine, Foreman Dampwick's been going crazy trying to find you. He said something about some 'defiant trolls'.\n\nThe kaja'mite that our trolls are mining is critical ingredient in Kaja'Cola. That bubbly stuff is making us a fortune, and it's going to get you a promotion to Trade <Prince/Princess>!\n\nBut first, we have to get production flowing again. You'll find the foreman to the east. Here, give him this as an incentive to get his act together.", sourceObjective = "Deliver Sassy's Incentive to Foreman Dampwick at KTC Headquarters on Kezan.", progress = "Um... everything's going great. Yeah.\n\nWhat's that?", completion = "A gift from Sassy? I hope it's a bonus!", sourceObjectiveStatus = "unverified-source-field" }
quests[14140] = { id = 14140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop The Aggressors", description = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target.\n\nThe crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", sourceObjective = "Giranan the Blooded at the Argent Tournament Grounds wants you to kill 10 Kvaldir.", completion = "Your actions have shown that we Sunreavers are far better allies to the Argent Crusade than the Silver Covenant and it is we who will be triumphant.", sourceObjectiveStatus = "unverified-source-field" }
quests[14141] = { id = 14141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormok Wants His Snobolds", description = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold.\n\nIf the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", sourceObjective = "Use the Weighted Net to capture 8 Snowblind Followers and bring them to Tylos Dawnrunner at the Argent Tournament Grounds.", progress = "Have you managed to round up those snobolds yet? Gormok's anger shows no signs of lessening.", completion = "The sooner we get these stinking things out of my sight and into their cage, the faster my mood will improve. I wish the Argent Crusade had given the Silver Covenant the care of this creature. They're going to have to get their hands dirty when the battle for Icecrown Citadel starts and I have a feeling they'll prove fragile and fussy allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[14142] = { id = 14142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Really Done It This Time, Kul", description = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tourney grounds, Kul gathered the aspirants for an attack.\n\nThey were easily captured, and now Kul languishes in a cage on the platform in the camp. I am sure that the cult will sacrifice the prisoners unless we can rescue them. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants.", sourceObjective = "Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker's Watch and return to Girana the Blooded at the Argent Tournament Grounds.", progress = "Did you free Kul and those hopeless aspirants?", completion = "Kul will live to embarrass himself again. That's far from the first time someone's had to save Kul from himself. With examples like him, it's no wonder most of the aspirants are taking up the habits of the Silver Covenant.", sourceObjectiveStatus = "unverified-source-field" }
quests[14143] = { id = 14143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Leg Up", description = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas.\n\nThey've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", sourceObjective = "Recover 10 Stolen Tallstrider Legs for Girana the Blooded at the Argent Tournament Grounds.", progress = "Were you able to recover any of the missing supplies?", completion = "These look a little worse for wear, but they're still edible. The crusaders will be glad to hear that we've had some success. Maybe we can give the half-eaten ones to the Silver Covenant. That would make my day.", sourceObjectiveStatus = "unverified-source-field" }
quests[14144] = { id = 14144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Mercy", description = "I've been listening to Confessor Paletress speak, and I must tell you, her words have made me think. We fight beside the crusaders, but we can learn from them, too.\n\nOff the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", sourceObjective = "Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Girana the Blooded at the Argent Tournament Grounds.", progress = "Have you seen to the spirits of the slain Tualiq villagers?", completion = "<Girana accepts the prayer book from you.>\n\nThank you. We don't always see eye-to-eye with the crusaders, but I've learned a lot from Confessor Paletress in my time here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14145] = { id = 14145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Do You Feed a Yeti, Anyway?", description = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep.\n\nThe crusaders weren't fond of my suggestion that we feed some Silver Covenant members to the beast. The creature prefers shark meat, so I want you to fly down to the Crimson Dawn, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", sourceObjective = "Tylos Dawnrunner at the Argent Tournament Grounds wants you to bring him 3 pieces of North Sea Shark Meat.", progress = "I hope you have something to feed Icehowl, otherwise I really will start bringing Silver Covenant members down to his cage.", completion = "I'm glad we've gotten that done. It's not the most glorious task in the world, but when we partnered with the Argent Crusade, we promised to do all they asked of us without complaint. Of course, the same cannot be said of the Silver Covenant.", sourceObjectiveStatus = "unverified-source-field" }
quests[14146] = { id = 14146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Gates!", description = "Egah - what's going on?\n\n<Screams, shouts, and the roar of combat fills the radio.>\n\n{name}! Get back here right away. Hurry back to the gates - we're under attack!\n\nHelp us fend off the invaders. I'm arming your grenade launcher!!", sourceObjective = "Labor Captain Grabbit needs you to rush back to the Rear Gate of Orgrimmar to slay 20 Night Elf Raiders.", sourceObjectiveStatus = "unverified-source-field" }
quests[14151] = { id = 14151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cardinal Ruby", description = "The Cardinal Ruby is said to be the finest gem in all of Northrend.  It sparkles like a crystal rose under the sun.\n\nBefore I teach you this recipe, I ask that you perform five epic gem transmutes to prepare your mind.  You can do any you like, and even do the same transmute many times.\n\nReturn to me when you are truly ready.", sourceObjective = "Linzy Blackbolt in Dalaran wants you to successfully transmute 5 epic gems with your alchemy skill. Acceptable transmutes include Ametrine, Eye of Zul, Dreadstone, King's Amber, and Majestic Zircon.", completion = "Very good, {name}.\n\nNow, the trick is to align the facets just right...", sourceObjectiveStatus = "unverified-source-field" }
quests[14152] = { id = 14152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue at Sea", description = "Champion, Captain Wavecrest and her ship were sent north to disrupt the Kvaldir in Hrothgar's Landing when they were intercepted by a Kvaldir raiding party headed to the Tournament Grounds. Unfortunately, the Kvaldir far outnumber the crew on board and are slowly taking over the ship.\n\nWe need you to go north to The Wavecrest in The Sea Reaver's Run, between the Tournament Grounds and Hrothgar's Landing and help the crew fend off the attack.  You should see the ship on the east side of the pass.", sourceObjective = "Head out to The North Sea and kill 8 Vrykul Berserkers and 3 Vrykul Harpooners attacking The Wavecrest.", progress = "Have you helped fend off the Kvaldir attack?", completion = "It seems things are worse than we initially thought.  You still made a valiant effort and saved many of The Wavecrest's crew's lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[14153] = { id = 14153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life of the Party", description = "Oh wow, baby! Everyone is here! Who cares about some stupid dragon?\n\nWe setup the party around the pool. Sounds like they're having a great time already. You are going to look so fine!\n\nWhy don't you head over to the pool and keep everyone entertained? I'll join you in a moment... I just have to grab my stuff.", sourceObjective = "Put on your Awesome Party Ensemble (Cool Shades, Hip New Outfit, and Shiny Bling) and then head over to the party at the KTC Headquarters pool to entertain 10 Kezan Partygoers.", progress = "How's the party going?\n\nYou look amazing! So beautiful!", completion = "Very nicely done, ma'am. The party appears to have been a smashing success!\n\nEr... what's that?", sourceObjectiveStatus = "unverified-source-field" }
quests[14154] = { id = 14154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Skin of His Teeth", description = "One of those mangy fleabags got Dempsey real good.  We cannot move him until we stabilize his bleeding.\n\nGive us a hand holding back these mongrels.  A couple of minutes is all we need, <brother/sister>!", sourceObjective = "Hold back the worgen atop the Gilneas City Prison for 2 minutes.", progress = "Getting there!  Careful or we'll lose him!", completion = "We did it, {name}.  Thanks to you a good man has survived.", sourceObjectiveStatus = "unverified-source-field" }
quests[14155] = { id = 14155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arborcide", description = "How's that shredder holding up? I think I can bring your emergency power supplies online - that'll recharge you when you're wounded.\n\nListen, these night elves are being strengthened by an ancient of war who's taken root just west of the gates. He's a big, giant tree. You know what to do! Take him out!\n\nYou were made for this!!", sourceObjective = "Use the Shredder to destroy the Talrendis Ancient. Emergency Backup Shredders are available at the Orgrimmar Rear Gate if you lose yours.", completion = "You did it, {name}! The invaders have pulled back. And they told me I was crazy for installing a grenade launcher on a woodchipper...\n\nGreat work with the shredder. With an impressive showing like that right here on the Warchief's doorstep, the Horde can't doubt what goblin technology can do for them. I owe you a big thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[14159] = { id = 14159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rebel Lord's Arsenal", description = "The arsenal Crowley speaks of is in the cellar of a building just west of here.\n\nIt is unnerving that artillery was smuggled inside the city by my enemies, yet it might end up saving Gilnean lives today.\n\nFind Josiah Avery and requisition the rebel artillery.  We will put the weapons to good use.", sourceObjective = "Speak to Josiah Avery at the Military District in Gilneas City.", completion = "Don't look at me!  Leave me alone!", sourceObjectiveStatus = "unverified-source-field" }
quests[14160] = { id = 14160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writ of Merit", description = "This fine parchment lists a great many accomplishments, achieved by {name}, in the tradition of jewelcrafting.\n\nReturn this writ to Timothy Jones in Dalaran for a proper reward.", sourceObjective = "Deliver the Writ of Merit to Timothy Jones in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[14161] = { id = 14161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basilisk Bashin'", description = "We moved this whole mountain to strip mine the minerals below. But what we didn't take into consideration were the subterranean basilisks that are now, uh, terranean. You look like you've got some initiative - go in there and kill some of those nuisances and I'll dip into our petty cash fund for you.", sourceObjective = "Kill 10 Greystone Basilisks in the Mountainfoot Strip Mine.", completion = "Good, good. One less nuisance to worry about.", sourceObjectiveStatus = "unverified-source-field" }
quests[14162] = { id = 14162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Horzak", description = "You've done a bangup job getting our lumber operations in order. But word on the wire is that we're falling under our stone quota. You'd think if we could move mountains, we could gather up a few rocks...\n\nWell, that's not my problem, but maybe you can make it yours. Report to Horzak Zignibble up ahead at the Orgrimmar Rocketway Exchange. See if you can't help him straighten out his operations. Just follow the road northeast and find him in the rocketway tower.", sourceObjective = "Find Horzak Zignibble at the Orgrimmar Rocketway Exchange in Azshara.", completion = "You're here to help? Excellent! Here, sign this indemnity waiver. And here, this noncompete clause. Let's get you started!", sourceObjectiveStatus = "unverified-source-field" }
quests[14163] = { id = 14163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Isle of Conquest", description = "As we get closer to victory in Icecrown, it's become more apparent that our armies are going to have to deal with the Horde before they can deal with the Lich King.\n\nThe elite guard known as the Kor'kron has been deployed to block our advance in the Isle of Conquest.  The isle is of vital strategic importance, {name}.  See to it that our lads prevail!", sourceObjective = "Win an Isle of Conquest battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde will never be a match for our forces as long as we have people like you on our side, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14164] = { id = 14164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Isle of Conquest", description = "Victory in Northrend will be ours soon... but not until we obtain a foothold in Icecrown to transport and supply our forces.\n\nThe Isle of Conquest is an ideal location.  It is easily defensible and rich in resources.  The Alliance have reached the same conclusion and have sent the Seventh Legion to wrest control of it from our forces.\n\nGo, {name}, and ensure that the Horde prevails at any cost!", sourceObjective = "Win an Isle of Conquest battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Nothing will stand between us and total victory.  For the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[14165] = { id = 14165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Cold", description = "Workers act like it's their job to complain. If it isn't the backbreaking labor, the long hours, or the low pay, it's being turned to stone by basilisks. It's always something!\n\nBut I'm thinking maybe this whole workers-to-stone business could be a big moneymaker for me. What if those guys are now high-quality stone? My whiny employees could be worth more to me as luxury building materials than a source of labor! Grab a stonified mountainfoot miner and haul him or her back to me.", sourceObjective = "Collect a stonified Mountainfoot Miner from the Mountainfoot Strip Mine and bring him or her back to Horzak Zignibble at the Orgrimmar Rocketway Exchange.", completion = "Well well, let's take a look at what we got here...\n\n<Horzak examines the shattered remains of the poor petrified miner.>\n\nBah! Crumbly! Useless. Wouldn't even make a good countertop. My miners may be mediocre workers, but they make lousy bricks.\n\n<Sigh>. Well, I suppose we should re-fleshify these guys so I can get some return on my investment.", sourceObjectiveStatus = "unverified-source-field" }
quests[14166] = { id = 14166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Dalaran Spirit in Dalaran's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", sourceObjectiveStatus = "unverified-source-field" }
