quests[14177] = { id = 14177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", sourceObjective = "Acquire some Bread of the Dead and give it to the Cheerful Troll Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday.", sourceObjectiveStatus = "unverified-source-field" }
quests[14178] = { id = 14178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[14179] = { id = 14179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, {name}.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", sourceObjective = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "We've come one step closer to achieving total victory over the Horde.  We cannot allow the enemy to obtain a foothold in this world or any other.", sourceObjectiveStatus = "unverified-source-field" }
quests[14180] = { id = 14180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "What news do you bring from the front, {name}?", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[14181] = { id = 14181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back already.  Do you bring news of victory?", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[14182] = { id = 14182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", sourceObjective = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "You bring honor to us all, {name}.  We must show the enemy that we will fight them wherever we find them.", sourceObjectiveStatus = "unverified-source-field" }
quests[14183] = { id = 14183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Do you bring news of victory?", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[14184] = { id = 14184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Time Has Passed", description = "<Weakly, Furien beckons you near and struggles to speak.>\n\nCareless... I was shot down by Alliance fire...\n\nYou must... inform my sister.\n\nTake my mount, {race}... he'll bring you to her...\n\n<Furien expires.>", sourceObjective = "Furien at Tethris Aran wants you to ride his Dragonhawk to Furien's Post and inform his sister, Cerelia of his death.", completion = "What!?\n\nFurien!! My brother is no more?\n\nThey must pay! All of them!", sourceObjectiveStatus = "unverified-source-field" }
quests[14188] = { id = 14188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Furien!", description = "This cannot be!\n\nMy dear brother - slain by Alliance scum!\n\nThey must be made to suffer, {race}! Find a way to bring them pain! I shall not rest until it is so...\n\nFurien had been researching ancient artifacts in the eastern regions before his death. Speak to Sorrem. Perhaps he can direct you in my brother's footsteps.", sourceObjective = "Cerelia wants you to speak with Sorrem at Furien's Post.", completion = "Furien's passing is... regrettable.\n\nI shall do all that I can to assist you in avenging his death.", sourceObjectiveStatus = "unverified-source-field" }
quests[14189] = { id = 14189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Translation", description = "It is true that Furien dedicated his last days to a special research project. What that was, he would not share with me.\n\nFortunately, I was able to recover his journal, but it's written in a code that I cannot decipher.\n\nPerhaps there is a clue to its translation in the region to the east where he spent his time.\n\nTake the journal, {class}, and speak with Narimar when you are ready to investigate this mystery.", sourceObjective = "Sorrem wants you to find the Ancient Tablets.\n\nSpeak to Narimar at Furien's Post to ride to where Furien was known to study.\n\nProvided item:", completion = "Comparing the characters on the ancient tablet to those in Furien's journal, it is clear that there is a distinct correlation.", sourceObjectiveStatus = "unverified-source-field" }
quests[14190] = { id = 14190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Prism", description = "There's got to be a way to reverse the basilisks' stonification. Those irritating night elf saboteurs who have been lurking around my mine must know something we don't. They seem to be immune to the gaze of the beast!\n\nI want you to find out their secret, {name}. Pick off a few of the Talrendis saboteurs skulking about in the rear of the strip mine and get a sample of whatever charm or ding-dong they're wearing to give them immunity. Radio me from the main forge building once you're successful.", sourceObjective = "Acquire a Crystal Pendant from a Talrendis Saboteur in the Mountainfoot Strip Mine.", progress = "<Strange goblin speakers hiss and crackle.>", completion = "<Zignibble's voice squawks over the speakers.>\n\nIs that you, {name}? Still alive? You aren't trashing my explosive stockpiles are you?\n\nHmmm... you say you found a clear crystal pendant. That makes sense. A perfect prism would refract the gaze of the basilisk. Maybe we can use this to our advantage. Time to drop some science!", sourceObjectiveStatus = "unverified-source-field" }
quests[14191] = { id = 14191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furien's Footsteps", description = "You can decipher bits and pieces of the text, but it will require extensive study before Furien's work becomes coherent.\n\nFor now, as you look off to the northeast, you think you can make out some of the ruins depicted in the journal.\n\nFrom what you can tell, these ruins seem to have been of some significance to Furien's research.", sourceObjective = "The Ancient Tablets at the Shrine of Elune have directed you to visit three of the prominent ruins in Sargeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[14192] = { id = 14192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prismbreak", description = "If that prism of yours is tuned to refract a basilisk's gaze, we can use its crystal properties to reverse the process. All we need is a source of power.\n\nIn the weapons cabinet to your right, you'll find our prototype laser mining drill. I loved that thing but the near daily dismemberments got to be a real bother. Grab the laser drill and swap out the lens with that crystal of yours...", sourceObjective = "Take the Crystal Pendant to the Weapons Cabinet in the Mountainfoot Strip Mine Headquarters.", progress = "<The weapons cabinet is loaded with heinous and broken experimental devices, some of which still have goblin limbs attached. You discover the laser drill lovingly ensconced in a velvet-lined wooden case.>", completion = "<You pop out the lens assembly and slide the crystal into place. The weapon hums ominously.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14193] = { id = 14193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing a Couple of Melons Won't Fix", description = "The markings on the ruins here make one thing clear: There is something special about the old fountain in the Sanctuary of Elune.\n\nIt would seem that one could expect special power from washing their face in the fountain. First, of course, there would need to be something in the ancient fountain with which to wash.\n\nPondering this problem, you spot a melonfruit at the base of a nearby tree....", sourceObjective = "Gather 8 Melonfruit.", completion = "After filling it with liquid from the melons, you proceed to wash your eyes from the ancient font.\n\nUpon opening your eyes, you are able to see the spirits of ancient elves, still faithfully carrying out rituals to their goddess.", sourceObjectiveStatus = "unverified-source-field" }
quests[14194] = { id = 14194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refleshification", description = "<The nearby radio calls out to you.>\n\nHey {name}, you got that gun? Good! Don't point it directly at your eye.\n\nAim that baby at my stonified workers and the refracted light should reverse the petrification process. Or it will melt them. Whatever. Return my workers to a state of profitability! And if the refleshification process makes them crazy-go-nuts, they should be killed for insurance purposes. Horzak OUT!", sourceObjective = "Use The Refleshifier to de-stonify eight Mountainfoot Miners within the Mountainfoot Strip Mine.", progress = "Hey look, all your limbs are intact.", completion = "Ah, good. Now we can get these slackers back to work. You've earned a cut of the profits though - minus the usual company fees. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[14195] = { id = 14195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Becoming Clearer", description = "Something has changed... perhaps a side-effect of Elune's cleansing ritual.\n\nWhile it's by no means perfect yet, your understanding of the ancient language in the journal has vastly improved.\n\nThe ruins in the northern mountains of Sargeron appear to be the main focus of Furien's enthusiasm. Something there, he felt, would aid him in driving the Alliance from this region.\n\nYou close the journal determined to find this ruin and discover its secrets.", sourceObjective = "Furien's Journal has directed you to find the ruined Palace of Elune in northern Sargeron.", progress = "This appears to be the ruin depicted in Furien's Journal.", completion = "It is clear to you now why you were guided here.\n\nYou recognize this ancient runestone from Furien's final journal entry:\n\n\"The ancients revered the gems created by this mystical object, claiming that they were gifts from the goddess herself. It was believed that they were weapons capable of delivering them from any enemy.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[14196] = { id = 14196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firestarter", description = "You are now able to understand the script in which the journal was written.\n\nAlong the runestone, it is explained that the monument's gemstones were imbued with the power to summon a firestorm.\n\nThe storm could grow to be a mighty weapon either through sustained worship of Elune, or charged by spiritual energies of the fallen.\n\nLooking down upon the newly revealed ghosts of Elune's disciples, you reason that you have neither the time, nor the inclination to worship the goddess of your enemy....", sourceObjective = "You are to create a Raging Vortex by defeating 7 Disciples of Elune in the presence of your firestorm.\n\nShould you lose your Vortex Gem, another can be obtained from the Ancient Vortex Runestone.", completion = "It is done! Furien's exhaustive research was not in vain.\n\nThe raging Vortex is ready to be unleashed upon your enemies at last!", sourceObjectiveStatus = "unverified-source-field" }
quests[14197] = { id = 14197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quota to Meet", description = "Mountainfoot iron is a brittle alloy, but with the right bribes it meets goblin safety standards. Zignibble here is having trouble on the production end of things, but that doesn't change any of my deadlines. I've got a quota to fill!\n\nHead down into the Mountainfoot Strip Mine and gather up any ingots of Mountainfoot iron you find. There should be piles of it smelted and ready for shipment.", sourceObjective = "Gather 20 ingots of Mountainfoot Iron from the Mountainfoot Strip Mine in Azshara.", progress = "Did you get my shipment together?", completion = "Well done! When it comes to iron, always pick quantity over quality.", sourceObjectiveStatus = "unverified-source-field" }
quests[14198] = { id = 14198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rider on the Storm", description = "You cannot help but to feel a twinge of pride, having unlocked this long lost secret of the ancient worshippers of Elune.\n\nYou now possess the power to inflict great damage upon your enemy.\n\nAs it was Furien's tireless work that made this possible, it only seems right that the weapon should be unleashed upon those who took his life.\n\nThe Alliance scum at Nijel's Point shall pay for their offenses against the Horde!", sourceObjective = "Use the Raging Vortex Gem at Nijel's Point Ruin. While commanding your firestorm, kill 40 Nijel's Point Defenders and burn 15 Nijel's Point Merchants.\n\nShould you lose your Raging Vortex Gem, you may acquire another from the Ancient Vortex Runestone.", completion = "Very impressive, {class}.\n\nYou completed Furien's work and rained vengeance down upon his killers.\n\nYou have brought peace to my brother's soul, and to my mind. Please accept this gift for your diligence.", sourceObjectiveStatus = "unverified-source-field" }
quests[14199] = { id = 14199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: The Black Knight", description = "My counterpart, Archmage Timear, has asked me to warn you of something dire. Soon, you will be participating in the Trial of the Champions at the Argent Coliseum in Icecrown. You must beware of interference from one known only as the Black Knight.\n\nBring me a fragment of his soul that the Kirin Tor will know he is dealt with. I am told that failing to do so will be your own undoing.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with a Fragment of the Black Knight's Soul.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Did the Black Knight appear unexpectedly as Timear foresaw?", completion = "It is good to see that you have emerged victorious from the trial. Truly, you are a champion, not only of the Argent Crusade, but indeed of the Kirin Tor as well.\n\nOne can only hope that you have dealt the final blow to that dark villain and that's the last that we will see of him.", sourceObjectiveStatus = "unverified-source-field" }
quests[14201] = { id = 14201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Stories in the Sand", description = "The ruins around Lake Mennar, to our east, have a tale to tell. The lesser races - like those clumsy dwarves - would go after the truth with picks and shovels. <Malynea wrinkles her nose.> We'll be using more elegant methods.\n\nMy scrying magic is somewhat rusty, but with the right trinket I should be able to peer through the shrouds of time. The bones of my forefathers have long since rotted away but some of their personal treasures may remain - bring me some.", sourceObjective = "Collect 5 Recovered Artifacts from the ruins around Lake Mennar in Azshara.", progress = "Have you gotten your hands dirty for me?", completion = "<Malynea furrows her brow and begins sifting through the artifacts you brought her.>\n\nSo the spirits of the dead still haunt those old stones, hm? Well {name}, as it happens, I'm counting on their help. Let's see what the dead have to say...", sourceObjectiveStatus = "unverified-source-field" }
quests[14202] = { id = 14202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey the Lakeshore", description = "All these cruddy ancient ruins have to be bulldozed if we're ever to see Azshara's full potential. Look on my map here - you see Lake Mennar, to the East? I'll tell you what I see: a future rocket fuel depot!\n\nBut we need an accurate lay of the land before we can clearcut, bulldoze, landfill, and pave over that lake. All of my surveyors have been spooked off by the oogly-boogleys haunting that area. Escort one of my Jr. grade surveyors to the area and take readings from the equipment that's been set up.", sourceObjective = "Escort a Goblin Surveyor to the three pieces of Surveyor's Equipment that surround Lake Mennar, and defend her while she takes readings. Another Surveyor can always be summoned with your Surveyor's Beacon.", progress = "No buncha dead elves can put a stop to progress. Not on my watch!", completion = "Beautiful work! Now that we know the area better, we can tear this lake a new one.", sourceObjectiveStatus = "unverified-source-field" }
quests[14203] = { id = 14203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", sourceObjective = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", sourceObjectiveStatus = "unverified-source-field" }
quests[14204] = { id = 14204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Shadows", description = "He turned into one of them... didn't he?  How do we even begin to fight an enemy that can do this to us?\n\nMy father's arsenal's certainly a good start, I suppose.\n\nWorgen are hiding in the alleys ahead.  Take one of my mastiffs to find them more easily.\n\nWe're going to need to clear the way ahead if we're going to move these cannons above ground.", sourceObjective = "Defeat 6 Bloodfang Lurkers.", progress = "Is it done yet, {name}?", completion = "Excellent.  I'll start rounding up some help to get these cannons positioned.", sourceObjectiveStatus = "unverified-source-field" }
quests[14209] = { id = 14209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunk in the Trunk", description = "Those ancient ruins have survived ten thousand years of wind and weather, so I brought out my biggest and bestest bulldozer to flatten 'em. I call her \"Margene.\"\n\nBut my dozer's been letting me down lately, {name}. The moment I drove her into those haunted woods, her engine seized up with a spine-chilling howl. Now my engineers tell me something's clogging her valves. Go over there and inspect Margene's engine compartment, and bring me back a sample of whatever gunk has her stalled.", sourceObjective = "Inspect Clubnik's Dozer and collect a sample of the Ectosplatter that's gumming up the engine.", progress = "Margene is one heck of a machine, isn't she?", completion = "Busted ball bearings! Look at this stuff - ugh, SMELL this stuff - my poor, poor dozer!\n\n{name}, I consider myself a goop expert and this here goop ain't natural. It's supernatural. This is ghost goop. We're going to need more than a mechanic...", sourceObjectiveStatus = "unverified-source-field" }
quests[14212] = { id = 14212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacrifices", description = "You don't have to do this, {name}.  You've done more than enough already.\n\nBut if you decide to stay... I'd be a fool to turn you away.\n\nMy men have fortified their position inside the cathedral and are ready for what comes next.\n\nI'm about to head there and take as many of these flea-ridden devils with me as I can.  You're welcome to come along for the ride.", sourceObjective = "Ride with Lord Darius Crowley and round up 30 Bloodfang Stalkers.", completion = "Brace yourself, {name}.\n\nHere they come.", sourceObjectiveStatus = "unverified-source-field" }
quests[14213] = { id = 14213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Pounds of Flesh", description = "According to Furien's Journal, this ancient brazier was placed here for the performing of sacrifices.\n\nAs far as you can make out from the entry, a blessing is bestowed upon the being who places the flesh of Elune's enemies on the brazier's burning embers.\n\nLooking around, you determine that the satyrs who now possess this region would likely qualify.", sourceObjective = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier indiscriminately endows you with a blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14214] = { id = 14214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Greymane", description = "It's time, {name}.  We'll take it from here.\n\nTell King Greymane that my father's arsenal will be at his disposal.  There's more than enough firepower here to blow the worgen from here to the north sea.", sourceObjective = "Speak to King Genn Greymane in the Military District.", completion = "I knew Crowley would come through.  His weapons will be more than useful to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14215] = { id = 14215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories of the Dead", description = "The runes on this ring you found are still legible: it was given to \"Kalytha\" when she was granted admission to the Academy. With the right spell or two, this personal trinket of hers is the gateway to her soul.\n\nTake the ring back to Lake Mennar. Kalytha's spirit should now be visible to you on the shore of the lake. Touch her and the ring will allow you to see the world as she sees it, forever reliving her final hours. Probe her mind, {name}! Speak to the others and learn the secrets of Lake Mennar...", sourceObjective = "Take Kalytha's Ring to the shores of Lake Mennar. Touch the Spirit of Kalytha to relive her memories. Speak to the other spirits until you've learned the secret of Lake Mennar.", completion = "You reel as the spirit's vision fades, relieved to once again feel the earth beneath your feet and the comforting rhythm of your own quickened heart.", sourceObjectiveStatus = "unverified-source-field" }
quests[14216] = { id = 14216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Sarcen Stone", description = "Before she died, Kalytha was charged with burying something at the bottom of the lake, a powerful artifact that the archmages of Mennar spent their last moments creating. No doubt Malynea Skyreaver will want to see the artifact, presuming it still exists. You resolve to search the bottom of Lake Mennar for the Sarcen Stone.", sourceObjective = "Retrieve the Sarcen Stone from the bottom of Lake Mennar.", progress = "Did you discover anything at the lake? You're soaking wet.", completion = "A Sarcen stone? That's the stuff of legend - let me see that!\n\n{name}, Sarcen stones are used to redirect the ley lines of magical energy. You realize what this means? The mages of Mennar weren't staying behind out of misguided loyalty. They sacrificed their lives in order to create this artifact in an attempt to draw energy away from the portal through which the demons were flooding Azeroth. They were buying time for the rest of the world to fight back! History never recorded their deeds. What a discovery!", sourceObjectiveStatus = "unverified-source-field" }
quests[14217] = { id = 14217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrical Offerings", description = "You find it most amusing to think that this ancient relic is bestowing upon you a blessing meant for your enemies.\n\nYou determine to make as much as you can of this unintentional gift.", sourceObjective = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier indiscriminately endows you with a blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14218] = { id = 14218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Blood and Ash", description = "The time has come, {name}.  If we're going to put a dent in their numbers, the time is now.\n\nWe have the position.\n\nWe have the firepower.\n\nAll that remains to be seen is whether we have the courage... and I sure don't see a coward standing in front of me.", sourceObjective = "Slay 80 Bloodfang Stalkers using the Rebel Cannons.", progress = "We must take out as many of them as we can, {name}.", completion = "You've done well, {name}.  You've done more than could be asked of any Gilnean.\n\nWe're running low on ammunition.  It's time to regroup inside now.", sourceObjectiveStatus = "unverified-source-field" }
quests[14219] = { id = 14219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Hilt!", description = "You immediately recognize this statue from a sketch in Furien's Journal.\n\nThough the words associated with the entry elude you, the sketch seems self-explanatory. After battle, the enemies' weapons were to be cast upon the basin in exchange for a divine gift of some sort.\n\nAs you ponder this ritual, the glint of steel catches your eye from a nearby weapon rack....", sourceObjective = "You are to collect 20 Satyr Sabers from the weapon racks and various satyrs in the region, then place them upon the statue, Elune's Handmaiden.", progress = "The statue stands expectantly.", completion = "With the ritual completed, you are awarded a divine gift.\n\nYou can't help but wonder what Elune would think of someone such as you receiving one of her boons.", sourceObjectiveStatus = "unverified-source-field" }
quests[14220] = { id = 14220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is the End" }
quests[14221] = { id = 14221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Surrender, Sometimes Retreat", description = "We had enough ammunition to carry on the civil war for another month.  Yet the worgen's numbers are such that we're nearly spent.\n\nWe don't want to be caught out here in the open when that happens.  Fall back inside the cathedral and report to the boss.  I'm sure old Crowley will know what to do next.", sourceObjective = "Speak to Lord Darius Crowley inside the Light's Dawn Cathedral.", completion = "We've given them everything we have... yet still they come.  Do not worry, {name}.  We'll slay many more before today is over.", sourceObjectiveStatus = "unverified-source-field" }
quests[14222] = { id = 14222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Stand", description = "We've got a good chokepoint here, {name}.  Feel free to say a prayer if that's your sort of thing.\n\nTake courage and let's kill these mutts.", sourceObjective = "Kill 8 Frenzied Stalkers.", completion = "They... they've stopped coming.\n\nNo, {name}.  That's not a good thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14223] = { id = 14223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace of Mind", description = "We are a forward post, charged with monitoring potential adversaries. Once the Horde launches its Desolace campaign, our work here will ensure that nothing takes us by surprise.\n\nRecently, one of our scouts was caught and sacrificed by the Burning Blade at their stronghold to the east. Since then, we've been assaulted with threats and taunts from a Burning Blade wretch named Kohor.\n\nTheir days here are numbered, but I will pay handsomely for that one to be silenced now!", sourceObjective = "Sorrem at Furien's Post wants you to kill Kohor.", completion = "It is done.\n\nSorrem should be able to sleep in peace now that Kohor's threats have been silenced.", sourceObjectiveStatus = "unverified-source-field" }
quests[14225] = { id = 14225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Know It When You See It", description = "With his dying breath, Kohor mentioned the summoning of a demon that could threaten the entire region.\n\nHe may have been bluffing, but that's not a chance worth taking.\n\nThis cannot wait for the Horde's invasion of Desolace to take shape. You must scour Thunder Axe Fortress for clues and bring an end to this potential threat.", sourceObjective = "Sorrem at Furien's Post wants you to find the Ancient Summoning Ritual in Thunder Axe Fortress.", sourceObjectiveStatus = "unverified-source-field" }
quests[14226] = { id = 14226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble Under Foot", description = "Look at you. Doing errands. Quite responsible of you. You're moving up up up, you are... up up!\n\nThere be demons ahead! Demons of many unpleasant kinds. Demons that would quite like your innards! Legash demons of a southeasternly heading! But do not worry. No no, no reason to worry, for I shall provide you with a companion!\n\nPoint, bugify, squash. Point, bugify, squash! Quite efficient. Quite messy too... but again, worry not. No no, worry not, for afterwards, we don't have to clean up!", sourceObjective = "Use your Personal Arcane Assistant to turn 12 Legash demons into insects and then squash them.", completion = "<Archmage Xylem appears to be doing some kind of dance as he turns to you.>\n\nDo not fret, and better yet, do not forget, to do not let the bug juice set or you will regret... well, you'll regret the smell of your boots really! It won't smell good today and it won't smell good even more tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[14227] = { id = 14227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Their Heads Together", description = "So it's true....\n\nThe parchment you discovered in Thunder Axe Fortress details a powerful summoning ritual. One stronger than the Burning Blade have ever been known to possess.\n\nClearly, this rite must be stopped at all costs!\n\nPerhaps if this demon were summoned forth prematurely the crisis could be averted.", sourceObjective = "Collect 100 Bleached Skulls from Thunder Axe Fortress, place them at the Burning Blade Summoning Circle, then kill Nazargen.", completion = "You diverted what would have been a serious crisis, {class}.\n\nIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.\n\nPlease accept this gift as our thanks for your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[14230] = { id = 14230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manual Labor", description = "The local demons seem to get quite a kick out of stealing all of our arcane manuals. I highly doubt most of them can even read, so they're probably doing it just to spite us.\n\nI could care less about most of the books they've taken, but they took an Abjurer's Manual that I'm going to need if there's any hope of keeping apprentices like you alive amidst Xylem's \"trials.\" Find the demons at the Lagash Encampment to the southeast and retrieve the Abjurer's Manual.\n\nThat's all. Scoot.", sourceObjective = "Retrieve the Abjurer's Manual from the Lagash Encampment.", progress = "And here you are... back... talking to me again. I assume this means that you have my book?", completion = "Peachy. Back to work then.\n\nThanks, snookums.", sourceObjectiveStatus = "unverified-source-field" }
quests[14231] = { id = 14231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Useless quest record" }
quests[14232] = { id = 14232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears Are Burning", description = "Sorrem has made no secret of his disdain for the Burning Blade at Thunder Axe Fortress.\n\nSurely, proof of their demise would be of value to him.", sourceObjective = "You are to bring 25 Burning Blade Ears to Sorrem at Furien's Post.", progress = "What have you there, {class}?", completion = "Ears of the Burning Blade?\n\n<Sorrem smiles.>\n\nWell done, {class}. This is just a shadow of what will soon become of that vile cult!", sourceObjectiveStatus = "unverified-source-field" }
quests[14233] = { id = 14233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs Can Write?", description = "Looking through the dead orc's belongings, you find a field journal. Though it is heavily water damaged, the writing is still legible, if barely.\n\nFlipping through the pages, an interesting story unfolds. Good thing you decided to study Orcish.\n\nLike the Trade Prince's yacht, the orcs were fired upon by Alliance warships. You do remember an orc warship that you passed right before the Alliance opened fire. Maybe they were firing on the orcs instead of your ship?\n\nStupid orcs! They got you sunk!", sourceObjective = "Take the Field Journal to Sassy Hardwrench at Shipwreck Shore on the Lost Isles.", progress = "{name}, find anything interesting in the cavern?", completion = "Orcs?! They were sunk and stranded too?  And now the Alliance are on the island? Do you think they're going to kill us?\n\n<Sassy looks thoughtful.>\n\nI think it's time for a little sitdown with these orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[14234] = { id = 14234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy", description = "I hate to ask you to do this, but I guess it's why they pay you the big bucks. Can you deliver that dead orc's field journal to whoever is in charge up at their camp?\n\nBased on the writing in the book, they should be located at the top of the island, up the incline past the Kaja'mite cavern to the southeast.\n\nGood luck, {name}. I always liked you.", sourceObjective = "Deliver the Field Journal to Aggra at the Horde Base Camp on the Lost Isles.", progress = "<The orc narrows her eyes at you.>\n\nYou must have been on the {race} slave ship that was sunk. What's that you have in your hand?", completion = "<The orc makes a move to grab the field journal from you, but then stops herself, exhaling deeply.>\n\nI apologize. It has been a very rough couple of days for all of us.\n\nI am Aggra. All of us here are what remains of the crew of the Draka's Fury.\n\nPerhaps we can work together. We have a common enemy in the Alliance. Their SI:7 assassins are all over this island and they're not going to stop until we're all dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[14235] = { id = 14235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vicious Vale", description = "Our hunter, Kilag Gorefang, and a few scouts, traveled into the vale down the path to the west. They're ...searching for... 'precious cargo'... that we were guarding when the filthy Alliance sunk our ship.\n\nThe way is blocked by deadly plants and they have not been able to break through.\n\n{name}, prove your worth as a goblin and a {class}. Journey into the Vicious Vale to find Kilag.", sourceObjective = "Find Kilag Gorefang in the Vicious Vale on the Lost Isles.", completion = "{race}, can you fight?\n\nFor your sake, I hope so. Otherwise, there may be no breaking through this hell of killer plants.", sourceObjectiveStatus = "unverified-source-field" }
quests[14236] = { id = 14236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weed Whacker", description = "<Kilag barely has time to acknowledge you between rifle shots, but his eye does linger a moment on your Goblin All-In-1-der Belt appreciatively.>\n\nNow is the time for creative solutions. Pull something out of that belt and get to work!\n\n<Thinking about the situation for a moment, an idea comes to your mind and it's just crazy enough to work!>", sourceObjective = "Use the Weed Whacker within your Goblin All-In-1der Belt to mow down 100 of the plants within the Vicious Vale.", progress = "There are still too many for us to get through.\n\nHave faith in yourself, {name}. Let your true warrior heart shine through.", completion = "I saw it with my own eyes, and still I do not believe it!\n\nYou have our thanks and the debt of our lives, little {race}. I hope that soon we can repay you the honor.\n\nMay I ask a small favor of you while my scouts and I move on?", sourceObjectiveStatus = "unverified-source-field" }
quests[14237] = { id = 14237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Movement", description = "Kilag should be in position by now. It is time for you to move forward to the Wild Overlook. The rest of us will pack up here and move out soon.\n\nJust follow the path northwest through the Vicious Vale. Not so vicious any longer thanks to you, eh?\n\nKilag and his scouts will be keeping themselves hidden just off the path, but the SI:7 assassins are sure to spot them soon, so hurry!", sourceObjective = "Find Kilag Gorefang and his scouts at the Wild Overlook on the Lost Isles.", completion = "Throm-Ka, {name}. We have a problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[14238] = { id = 14238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infrared = Infradead", description = "Keep your voice down. The glen north and west of here is crawling with Alliance assassins.\n\nUnfortunately, we haven't been able to spot them. The cowards! They hide and won't fight face-to-face.\n\nYou goblins are known for your wondrous goggles. Surely you have a pair that will allow you to see them?\n\nI need you to team up with one of my scouts and kill any of the SI:7 assassins that you spot.", sourceObjective = "Kill 10 SI:7 Assassins.\n\nIf something happens to your Orc Scout, return to Kilag to see if he has another for you to team up with.", completion = "Well done, {name}, well done. We'll make an orc of you yet!\n\nTime to move on. We'd better hurry.", sourceObjectiveStatus = "unverified-source-field" }
quests[14239] = { id = 14239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Go Into the Light!", sourceObjective = "It's up to you now. Are you going to come back to life and be the hero that your fellow survivors need you to be, or are you going to rest for eternity here?\n\nOnly you can decide.\n\nDon't go into the Light, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14240] = { id = 14240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Cliffs", description = "I sent Scout Brax forward along the road to the cliffs overlooking the beach to the west.\n\nI am going to put you onto Bastia. Travel down the path and let Brax know that we are going to take a different route.\n\nWe'll see you at the attack on the Alliance beachhead!", sourceObjective = "Speak with Scout Brax on the path down the cliffs north of the Savage Glen on the Lost Isles.", completion = "Hello, little {race}. Bastia is fast, no?\n\nWe have something very important that needs doing. Can you help us?", sourceObjectiveStatus = "unverified-source-field" }
quests[14241] = { id = 14241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to the Gyrochoppa!", description = "The Alliance have stolen something of vital importance to the Horde. It is being held out on their ships.\n\nAt the other end of the beach is a gyrochoppa. Our battlesworn will cover your approach.\n\nGo retrieve the keys to the flying machine from one of their operatives.\n\nFly out to their flagship, the Vengeance Wake, and retrieve our precious cargo!", sourceObjective = "Retrieve the Gyrochoppa Keys.", progress = "Hmm, looks like overly-complicated gnomish engineering with lots of unnecessary instrumentation and safety precautions.", completion = "Hmm, where the heck is the ignition?\n\nIt'll be a wonder if it flies without doing something weird, like turning into a chicken or shrinking down to the size of an ant.\n\nHey look, someone left their loose change in the ashtray! What else is in there?", sourceObjectiveStatus = "unverified-source-field" }
quests[14242] = { id = 14242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Cargo", description = "They said that their \"precious cargo\", whatever that is, is being held out on the Alliance ship, the Vengeance Wake.\n\nThere's only one thing to do... fly this thing out there and retrieve it!", sourceObjective = "Locate the precious cargo below deck on the Alliance ship, Vengeance Wake, off the shore of the Lost Isles.", completion = "If not for you, I would surely be on my way back to Stormwind to be paraded as a trophy and a slave.\n\nThe Alliance dogs found me unconscious on the shore and put me in this magical cage. It was keeping me from connecting with the elements.\n\nNo longer!", sourceObjectiveStatus = "unverified-source-field" }
quests[14243] = { id = 14243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Revenge", description = "Brothers of Earth and Fire, hear me! Sisters of the Water and Air, heed my call!\n\nAzeroth stands on the brink, its existence near an end! Lend me your power as in times past with my ancient ancestors. Allow me to channel your will through this child of Kezan.\n\nLet us put an end to those who would keep us from healing the world!", sourceObjective = "Use the powers of the Cyclone of the Elements to slay 50 Alliance Sailors.\n\nOnce this is done, you will be flown to the Wild Overlook.", completion = "You have done what few others could have, {name}. Our world owes you a debt larger than you can possibly understand.", sourceObjectiveStatus = "unverified-source-field" }
quests[14244] = { id = 14244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up, Up & Away!", description = "While you were rescuing the Warchief and saving us all from the Alliance, Foreman Dampwick built this rocket sling to shoot us over the shark-infested strait to the bigger island.\n\nLuckily for us, the foreman managed to salvage a Town-In-A-Box from the shipwreck. Once you get it set up, we'll have a town of our own. I can't wait to sleep in a bed again!\n\nDampwick's down there at the Landing Site, waiting for you. Why don't you take the next rocket over?", sourceObjective = "Survive the Rocket Sling shot across the Dire Strait.", completion = "{name}, I sure am glad you survived the trip... not everyone did!", sourceObjectiveStatus = "unverified-source-field" }
quests[14245] = { id = 14245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Town-In-A-Box", description = "The trade prince had an entire town-in-a-box in the ship's hold! I managed to recover it while you were out saving all of our skins.\n\nDo you want to do the honors? All you have to do is climb to the top of that huge pile of explosives and push the plunger, and whamo kablamo, instant town!", sourceObjective = "Climb to the top of the mountain of explosives and use the Town-In-A-Box Plunger.", completion = "<cough, cough!>\n\nHey! Where's the dock?! Someone stole the dock and the oil refinery from our town-in-a-box!\n\nWho would do such a thing?\n\nWhere's the Trade Prince?", sourceObjectiveStatus = "unverified-source-field" }
quests[14246] = { id = 14246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Early Adoption", description = "As the region becomes more lush, the creatures of the desert are being forced into increasingly confined spaces.\n\nA particularly distressing result is the impending extinction of the local swoops. Predators feast on the birds and their eggs when they take nest.\n\nI have acquired some swoop eggs from Tanaris and coated them with an irresistible pheromone. Place one in each nest you find, then protect it until a swoop comes to carry it off.\n\nYou will be doing a service to the balance of this land.", sourceObjective = "Place 3 Swoop Eggs in Swoop Nests and protect them until they are collected.", completion = "You have done well, {class}.\n\nThis land is in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14247] = { id = 14247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn Lands", description = "By authority of the Cenarion Circle, I am charged with turning these harsh lands into lush prairie.\n\nThe lands south of here welcomed the growth, but something here is fighting back - resisting the replenishment.\n\nPerhaps your eyes can succeed where mine have failed.\n\nPlease, {race}. Scour these lands and discover the source of the desert's stubbornness.", sourceObjective = "Thunk at Thunk's Abode wants you to find the Unnatural Outcropping.", completion = "You look around, scanning the horizon for what might be responsible for placing this stone here....", sourceObjectiveStatus = "unverified-source-field" }
quests[14248] = { id = 14248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Wanted", description = "Great news! Foreman Dampwick has uncovered a cave full of kaja'mite on the island! What are the odds?\n\nOf course, there's a downside. He took some of the survivors with him to help mine the ore, but none of them have made it out.\n\nCrazy as it sounds, the foreman said that there are monkeys in the cave... with mining picks! They're mining the kaja'mite! How is that even possible?\n\nCan you head southeast to the cavern? The foreman is standing just outside the entrance.", sourceObjective = "Speak with Foreman Dampwick outside of the Kaja'mite Cavern on the Lost Isles.", completion = "Boss! Er, well, I guess you're not the boss anymore, but still, good to see you!\n\nCan you believe it? We've got a cave full of intelligent killer monkeys mining kaja'mite!", sourceObjectiveStatus = "unverified-source-field" }
quests[14249] = { id = 14249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shear Will", description = "I'd be amazing! At archmagery. Amazing! He won't even talk to me because I don't have a stupid robe and hat. Pffft.\n\nThe most amazing archmage this land has ever seen can't just have any robe and hat. I need to show him that I'm something special, and I know just how to do it.\n\nGo out there and kill some of those hippogryph things. Bring me back a TON of feathers.\n\nYou heard me! A whole bunch of feathers! Go go, I'll have the robe ready for them by the time you get back.", sourceObjective = "Obtain 80 Pristine Thunderhead Feathers from the Hippogryphs near the Ruins of Nordressa.", progress = "My robe's looking pretty good. Did you bring those feathers?", completion = "Ha ha! Perfect! Let me toss this together really fast. The Archmage is sure to be taken in by my style!", sourceObjectiveStatus = "unverified-source-field" }
quests[14250] = { id = 14250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renewable Resource", description = "We're going to need some more animate basalt. There's only one reliable source for that in the area, a mountain giant named Balboa. We can't be killing the mountain giant if we want to keep stocked in the stuff long term, so we've just been chipping off pieces at a time.\n\nYou'll be able to see his path northeast and east of here. Find him, place the charge ahead on the path, and then hide until it goes off. Once he's cleared the area, you should be able to retrieve the basalt and bring it back to me.", sourceObjective = "Use the Arcane Charge to retrieve 5 Animate Basalt from Balboa near the Ruins of Nordressa.", progress = "I heard a few explosions. I can hardly tell if one of them was yours or not... these goblins can be quite a nuisance.", completion = "Good work. This should keep us for another few hours before we have to go back for more.\n\nHe doesn't seem to be the brightest of giants. I expect we'll be able to keep doing this for a while before he catches on.", sourceObjectiveStatus = "unverified-source-field" }
quests[14251] = { id = 14251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Beginnings", description = "There's never been danger of centaur attack this far north before. Someone put 'em up to it, I just know it!\n\nRegardless, I'm wiped out. I had everything invested in this haul.\n\nFortunately, there's one thing no centaur can take from me and that's goblin ingenuity! I'll start from scratch and build an empire!\n\n<Bizby spots a scorpion in the distance.>\n\nThere's always a market for poison. Whatdya say, friend?", sourceObjective = "Collect 15 Scorpion Stingers.", progress = "Let's have a look at those scorpion tails, friend.", completion = "This is how I got my start, you know.\n\nSlingin' poison to the rogues in Orgrimmar. Ahh, those were the days....", sourceObjectiveStatus = "unverified-source-field" }
quests[14252] = { id = 14252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Gold For Bad Tail", description = "I need a crateload of tail, {class}! And not just any kind of tail. The tail I'm after needs to be old - ancient even. The more decrepit the better.\n\nThe scales of a basilisk's tail are unique in that they harden with age without becoming brittle. The hardened scales are ideal for the production of certain armors.\n\nIt's been many years since I've been reduced to peddling lizard scales, but who knows, maybe it'll build even more character in me! If that's even possible....", sourceObjective = "Find 15 Aged Basilisk Tails.", progress = "How's the search for tail coming, {name}?", completion = "That'll do, {class}.\n\nA few more friends like you and I'll be back on my feet in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[14253] = { id = 14253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletch Me Some Plumage!", description = "Say, {class}, while you're out there exploring the desert wastes, do me a favor?\n\nKeep an eye out for Dread Swoops. Their oily feathers make for the best fletching, and to the right buyer they can fetch a handsome price.\n\nLucky for you, I know all of the right buyers!", sourceObjective = "Collect 25 Dread Swoop Feathers.", progress = "How is the search for swoops coming?", completion = "Well now, that's quite a load of feathers, {class}.\n\nThey'll make for a good pillow 'til I get 'em to market!", sourceObjectiveStatus = "unverified-source-field" }
quests[14254] = { id = 14254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Metal", description = "You have a strong feeling that this stone is somehow responsible for the region's refusal to accept the encroaching regrowth.\n\nLooking off to the west, you notice a trail of smoldering debris that appears to be related to this mystery.\n\nYou surmise that clearing the debris might assist Thunk's efforts here.\n\nAnd who knows what this stuff might be good for?", sourceObjective = "You are to collect 7 pieces of Element 116 and bring them to Bizby at Bizby's Caravan.", progress = "Whatcha got there, {class}?", completion = "What's this?\n\n<Bizby examines the ore.>\n\nWahoo! I know someone who will be most interested in acquiring these samples.\n\nMost generous in payment for them as well, I'll wager.\n\nHere, {class}. Take this as your finder's fee.", sourceObjectiveStatus = "unverified-source-field" }
quests[14255] = { id = 14255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethel Rethor", description = "We have plenty of enemies in this region without raising the ire of the Cenarion Circle.\n\nWhen we established our post here, we were asked to keep a watch over one of their researchers.\n\nKorrah was last seen at the tower to the west. Do be a dear and pay her a visit. It's been some time since we've bothered to check on her.", sourceObjective = "Cerelia at Furien's Post wants you to speak to Korrah at Ethel Rethor.", completion = "It is good that you have come.\n\nThere is grave danger looming here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14256] = { id = 14256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emerging Threat", description = "I am all that remains of my company, sent to monitor the many changes on this coast of Desolace.\n\nI have reported of the dramatic increase of naga here, but to no effect.\n\nMy peers are focused on other crises, so I must ask you, a stranger, to assist me in my research.\n\nFirst, though, allow me to show you the threat we face.", sourceObjective = "Korrah wants you to speak to her when you are ready to be shown the Naga threat.", completion = "So now you see. These are not a simple band of displaced naga, but a well organized army, capable of great devastation.\n\nDo you agree to assist me in my investigation?", sourceObjectiveStatus = "unverified-source-field" }
quests[14257] = { id = 14257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slitherblade Slaughter", description = "Time and again, the naga have proven to be enemies to the balance of nature. I have no qualms with the spilling of their blood.\n\nYour best efforts though, would barely put a dent in their forces here. Where one falls, two seem to rise in their place.\n\nI have a plan, {class}. Your objective is not merely to take the lives of the enemy, but to gather components necessary for the next stage of our investigation....", sourceObjective = "Collect 10 Slitherblade Bones from Slitherblade Naga, 30 Slitherblade Scales from Slitherblade Sorceresses, and 4 Slitherblade Fins from Slitherblade Warriors.", progress = "Have you collected the components I require?", completion = "You have done well, {class}. But I'm afraid that your work here is just beginning.", sourceObjectiveStatus = "unverified-source-field" }
quests[14258] = { id = 14258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortar the Point", description = "The Naga started making a move on the peninsula here after we finished building this rocketway terminal. But there's no problem in this world that can't be solved with gratuitous firepower! That's what my daddy used to say. Before the accident.\n\nI'm running short on supplies, though. Do me a favor and collect the mortar shells I left stockpiled in the Secret Lab just west of here. Keep me supplied and I'll let you call in the artillery strikes!", sourceObjective = "Collect 5 Goblin Mortar Shells from the Secret Lab complex in Azshara.", progress = "I hope you have more ammo for me. I've got nothing to shoot off over here but my mouth!", completion = "Sweet! Beautiful! Brilliant! Who loves you?\n\nWith my mortars re-supplied, I can help you as you assault the Naga east of here. Use these markers to call in an artillery strike anywhere on the cliffs, and I'll splatter the whole area with fiery hurt. Oh delicious, merciless, random destruction! I hope you're well-armored...", sourceObjectiveStatus = "unverified-source-field" }
quests[14260] = { id = 14260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Deep", description = "I have fashioned a charm that will allow you to infiltrate the naga, giving you the appearance of one of their own.\n\nWith this disguise, you will be able to speak and understand their language. They will be unable to discern your true identity.\n\nBut beware! The sharks and other sea creatures here will expose you for all to see. Avoid them at all costs.\n\nNow go. Speak to the Priestess of Azshara and do what you must to learn of their purposes here.", sourceObjective = "Use the Slitherblade Charm.", completion = "Don't just stand around, when there is so much to be done!\n\nMust I instruct everyone on each detail?", sourceObjectiveStatus = "unverified-source-field" }
quests[14261] = { id = 14261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Cold", description = "I've got the perfect solution to our drake problem. My very own Cryomatic 16.\n\nI originally developed it to freeze my workers during transport and between shifts so that I wouldn't have to feed and entertain them, but there were... complications. It should be perfect for dropping these drakes out of the sky though!", sourceObjective = "Use the Cryomatic 16 to freeze and kill 8 Sable Drakes.", completion = "What? So you didn't bring any of the drake pieces back? Disappointing.\n\nI knew I should have made you sign a contract before I sent you out...", sourceObjectiveStatus = "unverified-source-field" }
quests[14262] = { id = 14262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gut a Fish", description = "It tries my patience, defending against creatures who can disappear into the sea at will and emerge where they please. But I will not back down until their like has been wiped from Azshara.\n\nSpitelash Naga have slithered up the cliff walls and are besieging this post from the east. Destroy them, {name}. Gut them head to tail, so that they may know the full fury of my Horde.", sourceObjective = "Slay 6 Spitelash Stormfuries and 6 Spitelash Seacallers.", completion = "<Torg scans the horizon.> And still they come! They are like a plague, {name}. But with strength like yours, we will crush them. Someday.", sourceObjectiveStatus = "unverified-source-field" }
quests[14263] = { id = 14263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste of Thyme", description = "Living Ire Thyme. I must have more! Be quick about it, will you?", sourceObjective = "Collect 8 bundles of Living Ire Thyme near the Ruins of Nordressa.", progress = "Do you have that thyme for me?", completion = "Perfect. It's quite interesting how useful the most random things end up being to incantations of this sort.\n\nSo much more to learn!", sourceObjectiveStatus = "unverified-source-field" }
quests[14264] = { id = 14264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wetter Than Wet", description = "Neptulon's minions have arrived here and are doing all they can to thwart us. Clearly, they've discovered our motives.\n\nThis only confirms my suspicion that what we seek is indeed somewhere in these ruins!\n\nThese water elementals are no match for our forces! Take this trident and use it to destroy the worthless servants of the Tidehunter.\n\nWhen we find what we seek here, Neptulon himself shall fear for his life!", sourceObjective = "Defeat 5 Servants of Neptulon. (You must be in naga form when you defeat them.)\n\nIf you lose your Slitherblade Trident, speak to Valishj.\n\nIf you lose your Slitherblade Charm, speak with Korrah at Ethel Rethor.", progress = "Tell me, minnow. Have you done as I asked?", completion = "The enemy's ranks are thinning, little minnow.\n\nPerhaps you are worthy of assisting in our search....", sourceObjectiveStatus = "unverified-source-field" }
quests[14265] = { id = 14265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Instructor", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A fellow by the name of Cleese said you were one of his students and wanted to make sure you were all right.", sourceObjective = "Speak to Sergeant Cleese in the Military District.", completion = "{name}!  Where have you been?\n\nAnyway... it's great to see you in one piece.", sourceObjectiveStatus = "unverified-source-field" }
quests[14266] = { id = 14266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge", description = "You're alive, {name}!  That must mean I did something right.\n\nIt's a shame our lessons were cut off a little short.  But perhaps there's a thing or two I can teach you that might be handy in a time like this.\n\nTry out your new technique against the bloodfang worgen to our west.", sourceObjective = "Speak to Sergeant Cleese and learn Charge. Practice using Charge against a Bloodfang Worgen.", progress = "You're a quick study, {name}.  Don't get overconfident, though.", completion = "Excellent work!", sourceObjectiveStatus = "unverified-source-field" }
quests[14267] = { id = 14267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Sea Shrine", description = "The Naga invaders have set up a series of shrines along the cliffs. I don't know their purpose, {name}, but I believe they're strengthening our foes. I need someone to get in there and root out this threat.\n\nOne nearby shrine is lightly defended: Cross the first bridge east of here and then head north towards the bay. You'll find it on a small outcropping. Investigate that shrine and come back with some info I can use.", sourceObjective = "Investigate the Naga shrine for Torg Twocrush.", completion = "The stone in the center of this shrine emits a faint glow and roars with the power of the angry sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[14268] = { id = 14268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep Impact", description = "Queen Azshara seeks entrance into the plane of water, for what I do not know.\n\nShe believes that the ancients held the keys to finding its location.\n\nI have personally been charged with scouring the ruins in this region, and none shall rest until we discover the secrets we seek!\n\nSubmerged just to the north are a concentration of ruins. Use this staff to search through the rubble.\n\nReturn to me only when you have located that which we seek!", sourceObjective = "Priestess Valishj wants you to find the Ancient Engravings of Neptulon.", progress = "Could it be....?", completion = "Yes! You've found it!\n\nNeptulon's engravings... there can be no mistake!", sourceObjectiveStatus = "unverified-source-field" }
quests[14269] = { id = 14269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone's Looking for You", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A woman named Loren... she seemed a little disappointed when I told her you were all right.\n\nI think she mentioned she owes you money.", sourceObjective = "Speak to Loren the Fence in the Military District.", completion = "Oh, hey!  There you are!", sourceObjectiveStatus = "unverified-source-field" }
quests[14270] = { id = 14270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keystone Shard", description = "The air around this strange stone crackles with energy. The stone itself is smooth and icy cold. It pulses periodically as you run your hands over it, like the crashing of surf.\n\nA wedge-shaped piece appears to be missing from the top surface of the artifact. This 'keystone shard' is likely the key to unlocking the secrets of the stone. Search the grounds near the temple and locate the keystone shard.", sourceObjective = "Find the Keystone Shard nearby.", progress = "The Naga power stone pulses with an expectant hum.", completion = "The keystone shard slides into place and previously invisible runes suddenly erupt onto the surface of the stone, shimmering in blue and violet hues. Your knees buckle as powerful arcane currents suddenly race into your body...", sourceObjectiveStatus = "unverified-source-field" }
quests[14271] = { id = 14271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Twocrush", description = "A magical barrier pulses around you, chilling your bones. You feel secure behind this enchanted wall.\n\nTorg Twocrush will want to know what you've discovered here!", sourceObjective = "Return to Torg Twocrush at the Southern Rocketway Terminus in Azshara with news of your discovery.", completion = "An energy barrier, you say? This explains a great deal! I've seen firsthand how Naga leaders have been able to turn aside the blades of some of my best warriors.\n\nNow we know the source of their power, {name}. Let's finish this!", sourceObjectiveStatus = "unverified-source-field" }
quests[14272] = { id = 14272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eviscerate", description = "Good to see you alive!\n\nNo, of course I don't have that gold I owe you.  Now's not really the time to bring that up is it?\n\nListen, maybe I can teach you a trick or two that might save your skin with all the carnage going on.  I'd call it more than even then.  What do you say?\n\nAfter your lesson is over, try using your new technique against the Bloodfang Worgen to our west.", sourceObjective = "Speak to Loren the Fence and learn Eviscerate. Practice using Eviscerate against a Bloodfang Worgen.", progress = "Keep your head down and maybe the {race} will go for some other poor fool instead of us.", completion = "Don't get ahead of yourself now.  Just remember who taught you everything you know.\n\nAnd now let's see if we can get out of this city with our skins attached.", sourceObjectiveStatus = "unverified-source-field" }
quests[14273] = { id = 14273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shady Associates", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A strange fellow named Vitus... he was really giving me the creeps.\n\nHe kept talking about some \"forbidden knowledge\" he'd uncovered.", sourceObjective = "Speak to Vitus Darkwalker in the Military District.", completion = "A darkness has descended over our lands.  And not our kind of darkness, if you know what I mean.", sourceObjectiveStatus = "unverified-source-field" }
quests[14274] = { id = 14274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immolate", description = "It is true then!  You live!\n\nI never got a chance to share my greatest discovery with you.  From the depths of the nigh-indecipherable books of Balcephoth of the felshadows... I've learned the forbidden secrets of...\n\nImmolate!\n\nOf course I will share this knowledge with you... who else around here would appreciate such powerful understanding?\n\nGo now, and practice your new spell against the Bloodfang Worgen to our west.", sourceObjective = "Speak to Vitus Darkwalker and learn Immolate. Practice casting Immolate on a Bloodfang Worgen.", progress = "You're doing well, {name}.", completion = "Yes!  You can feel the power, can't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[14275] = { id = 14275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone's Keeping Track of You", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A man named Blake.  Said something about a plan to escape into the woods.", sourceObjective = "Speak to Huntsman Blake in the Military District.", completion = "{name}!  I knew you had to be around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14276] = { id = 14276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "So I've got good news and bad news.\n\nThe bad news is that there are more worgen in the woods than in here... so we really have no safe place to go to.\n\nThe good news is that I still have a thing or two to teach you.  Who knows the sort of skill that might save your life in a time like this.\n\nTry your hand at it against the bloodfang worgen to our west.", sourceObjective = "Speak to Huntsman Blake and learn Steady Shot. Practice using Steady Shot 2 times against a Bloodfang Worg.", progress = "You're a fast learner.  We'll show these {race} who the real hunters are.", completion = "Excellent work, {name}.  These {race} will regret ever setting foot in our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[14277] = { id = 14277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Inquiries", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  It was a mage named Myriam.  She mentioned something about you being \"ready.\"", sourceObjective = "Speak to Myriam Spellwaker in the Military District.", completion = "A disciple of the arcane always finds a way forward.  I'm glad to see you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14278] = { id = 14278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Sister", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  A member of the clergy, Sister Almyra, said that you were in great peril and needed the Light's protection.\n\nYou should go talk to her.  She seemed very concerned.", sourceObjective = "Speak to Sister Almyra in the Military District.", completion = "The Light is with you, {name}.  It's still quite a relief to see you.", sourceObjectiveStatus = "unverified-source-field" }
quests[14279] = { id = 14279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flash Heal", description = "You have much to learn, {name}.  And I've much to teach you.\n\nThese are perilous times, however, and I fear that we might have to accelerate certain lessons.\n\nHave no fear, <brother/sister>.  The Light will guide us through this.", sourceObjective = "Speak to Sister Almyra and learn Flash Heal. Use Flash Heal 2 times on a Wounded Guard.", progress = "You are learning swiftly, my dear.", completion = "You are blessed, {name}.  The Light shines upon you, even in these dark times.", sourceObjectiveStatus = "unverified-source-field" }
quests[14280] = { id = 14280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winds Know Your Name... Apparently", description = "Most of us made it here alive... but there are worgen on this side of the city as well.\n\nWe're going to continue heading south once everyone's accounted for.\n\nThat reminds me, someone was asking about you.  It was that harvest-witch, Celestine; she said the winds spoke your name.\n\nYou'd best hurry, {name}.  We're going to need you to get back to the worgen-smashing once you're done conversing with nature.", sourceObjective = "Speak to Celestine of the Harvest in the Military District.", completion = "We have been blessed today!  You are alive and well!", sourceObjectiveStatus = "unverified-source-field" }
quests[14281] = { id = 14281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Missiles", description = "The path ahead is difficult, {name}.  We must devote the entirety of our mental power to the task at hand.\n\nYet sometimes, that is not enough.  Sometimes the situation calls for raw firepower.\n\nI know just the spell for such a situation and I'll be more than glad to share it with you. Once you've learned it, practice using it against the Bloodfang Worgen to our west. You'll only get the chance to use your new spell after casting a different spell.", sourceObjective = "Speak to Myriam Spellwaker and learn Arcane Missiles. Use Arcane Missiles against a Bloodfang Worgen.", progress = "I always knew you were a quick study!", completion = "You've learned with such speed and ease.  Soon you'll be the one doing the teaching.", sourceObjectiveStatus = "unverified-source-field" }
quests[14282] = { id = 14282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Solved", description = "Your efforts have paid off. The great risks you have taken have proven worthwhile.\n\nYou have discovered the object of the nagas' desire and their reason for overrunning the coast of Desolace.\n\nAs for the engravings you've discovered, your duty is clear...", sourceObjective = "You are to bring the Ancient Engravings of Neptulon to Cenarion Researcher Korrah.", progress = "What have you learned, {class}?", completion = "The vision was true!\n\nYou have singlehandedly succeeded where others have failed.\n\nThe Circle will have no choice but to pay attention to these findings.", sourceObjectiveStatus = "unverified-source-field" }
quests[14283] = { id = 14283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rejuvenating Touch", description = "We were driven to the edge of extinction once before, {name}.  But we druids, keepers of the old ways, saved our people from famine.\n\nWhen we cut ourselves off from the outside world and our crops failed, it was our order who called upon the earth's blessings and restored the harvest.\n\nJust as we did then, it is best to put our fate in the hands of a higher power.  Join me now and learn what the wild has to teach us.", sourceObjective = "Speak to Celestine of the Harvest and learn Rejuvenation. Practice using Rejuvenation on a Wounded Guard.", progress = "The earth speaks to us, {name}.  It will not abandon us even in these perilous times.", completion = "Not bad at all.  Perhaps there is still hope for the old ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[14284] = { id = 14284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Revenant's Vengeance", description = "I am Hydronis, a servant of Neptulon the Tidehunter, Lord over all waters.\n\nAzshara and her sinister naga have arrayed themselves against my master, and seek a war with him. This is the first battle in what shall surely be a long struggle.\n\nI have fought bitterly, {race}, and have grown weary.\n\nIt seems that my actions here have attracted the attention of their priestess.\n\nAlone, I haven't the strength to overcome her. but perhaps together, we may prevail.", sourceObjective = "Hydronis wants you to mount him and defeat Priestess Valishj.", completion = "The priestess is no more...", sourceObjectiveStatus = "unverified-source-field" }
quests[14285] = { id = 14285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "There's only so much I can teach right now with all these worgen trying to dismember us.\n\nWe really should think about heading south with the other survivors.  We've been told that King Greymane is there.\n\nIf we stick together our chances of survival will increase... especially if you choose someone nutritious-looking to stand next to.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14286] = { id = 14286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14287] = { id = 14287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14288] = { id = 14288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "There's only so much I can teach right now with all these worgen trying to dismember us.\n\nWe really should think about heading south with the other survivors.  We've been told that King Greymane is there.\n\nIf we stick together our chances of survival will increase... especially if you choose someone nutritious-looking to stand next to.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14289] = { id = 14289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nThe others are going to need the aid of the Light in these troubling times.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14290] = { id = 14290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14291] = { id = 14291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety in Numbers", description = "I've taught you all that is practical for now.\n\nIt is time we joined with the other survivors.  The others mentioned that King Greymane and his royal guard are just south of here.\n\nWe should go there and seek safety in numbers.", sourceObjective = "Speak to King Genn Greymane in the military district.", completion = "You've done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[14292] = { id = 14292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of Our Enemy", description = "You have done us a great service, {class}.\n\nWhile they remain an imposing force, your efforts have kept an important artifact from the naga.\n\nI shall write to my peers of your findings. Meanwhile, the water revenant on Ranazjar Isle has stood alone against a steady onslaught of naga.\n\nI would have you find him and determine if there is some way we can assist him.", sourceObjective = "Cenarion Researcher Korrah wants you to speak with Lord Hydronis.", completion = "I have witnessed your actions here, {race}.\n\nYour presence here is both welcome and timely.", sourceObjectiveStatus = "unverified-source-field" }
quests[14293] = { id = 14293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Krennan Aranas", description = "All these years after the war and Crowley was still hiding enough firepower in that cellar to level half of the district.\n\nIt might have to come to that, unfortunately.\n\nWe can't open fire just yet, there is a civilian trapped on the other side of the prison.\n\nNot just any civilian, either.  Krennan Aranas is one of the most brilliant alchemists this world has known.\n\nOne of his potions saved my daughter, Tess, from dying soon after being born.\n\nTake my horse and rescue him.  Krennan must live.", sourceObjective = "Rescue Krennan Aranas.", completion = "Well done, {name}.  We'll make sure Krennan makes it out of the city alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[14294] = { id = 14294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Regroup", description = "We've done all we can here.  Let King Greymane know we've bought some time.\n\nI've a feeling it won't be long 'til the worgen are back in force.\n\nWe'll need to fall back to Greymane Court to the west, if that's the case.  It's the last place we can hold out without being trapped like fish in a barrel.", sourceObjective = "Speak to King Genn Greymane at Greymane Court in Gilneas City.", completion = "We're left with very few choices, {name}.  What we do next will be a critical decision.", sourceObjectiveStatus = "unverified-source-field" }
quests[14295] = { id = 14295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sisters of the Sea", description = "Two Naga witches have been masterminding the assault on this outpost. They've repelled direct attacks from some of my best grunts, but you can finish the job where others have failed.\n\nSeek out and slay Lady Silisthra and Lady Vesthra at the eastern edge of the cliffs, around the ruins of the ancient night elven colossus. You will first need to destroy the powerstones that give them their strength. Do not disappoint me, {class}!", sourceObjective = "Kill Lady Silisthra and Lady Vesthra by disabling their power stones.", completion = "Now THAT is how we used to handle serpents back in Durotar - we crushed them under our boots! You have done the Horde proud, {name}. As soon as my reinforcements arrive we'll mop up the rest of those vermin and claim this peninsula once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[14296] = { id = 14296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watch Your Step", description = "This is somewhat simple and somewhat not simple. All the way up there are Energy Conduits. Rather like this one right here one might say! Indeed, I do say.\n\nNow for you. You must use my jump pads to ascend the pinnacle, and you must touch all of the conduits you see along the way. When you get to me at the top, you should be all juicy with energy, because really that's the only way to be.\n\nAnd be sure to keep moving or you're likely to be sent for quite a trip!", sourceObjective = "Receive 6 Energized charges from the Energy Conduits as you ascend to the top of the Arcane Pinnacle.", progress = "No no no, you've got it all wrong. You were supposed to gather Energy from the Conduits before you came up here, remember?\n\nOne more time, with style!", completion = "It is in this moment that most of my apprentices wonder if there was a logical purpose to storing the energy for my portal in those conduits so that it has to be collected in such a fashion.\n\nOf course there's a purpose! I wish to study your behavior... your strategies, your mistakes, your frustrations, your triumphs. Those are the entire point of these trials.\n\nNow, more. More trials! Doesn't that sound exciting?! Of course it does.", sourceObjectiveStatus = "unverified-source-field" }
quests[14297] = { id = 14297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pro-liberation", description = "I knew these guys would be trouble as soon as we started building this tower. Scoffing our bribes. Stealing our workers.\n\nLabor isn't cheap with all the construction in Azshara. I need those men back!", sourceObjective = "Use Ironwrought Keys from cultists and dragonkin to free 4 Goblin Workers in Sable Ridge.", completion = "Thanks there, pal. Here's your commission.\n\nIf you'll excuse me, I've gotta get these slackers back to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[14299] = { id = 14299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylem's Asylum", description = "Quite marvelous of you! A pleasure to observe. Much to study.\n\nOff you go now, retire to my tower. Joanna will get you situated. I shall open a portal for you.", sourceObjective = "Take the portal to Archmage Xylem's tower and seek out Joanna inside.", completion = "Welcome! You seem to have survived the trials relatively unscathed. Good for you, love.\n\nYou look to have come with a purpose in mind as well. A question. Your thoughts are very loud, it's hard for me to not hear them.\n\nGo ahead then, hon. Ask away.", sourceObjectiveStatus = "unverified-source-field" }
quests[14300] = { id = 14300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Fire", description = "The Trial of Fire... oooh... sounds intimidating, doesn't it? No? Hm. Well I kind of thought so. Firsts are first, you touch the fire crystal and the portal to the trial opens.\n\nTo beat this trial, you have to hop around in the fire runes without getting hit by the fire. If you stay unflamed long enough, you win!\n\nThere are little signs to help you - fire hopping to its new rune, fizzles when a rune goes cold. You can figure that stuff out if you want. Or just guess! That's what most people do.", sourceObjective = "Complete the Trial of Fire by standing in the fire runes without getting hit by flame for 10 consecutive bursts.", progress = "Um, no. You're not done. Get back in there and get toasty!", completion = "Woo! Good for you! That trial really put a fire under your bottom.", sourceObjectiveStatus = "unverified-source-field" }
quests[14301] = { id = 14301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return and Report", description = "It is done! Together we were able to bring down a dangerous adversary.\n\nNeptulon himself shall hear of your exploits here, {class}. Allow me to extend you his thanks...\n\nYou should leave now. This place will not remain safe for long. Soon, the naga will seek vengeance for their priestess.", sourceObjective = "You are to return to Cenarion Researcher Korrah at Ethel Rethor.", completion = "Please accept this reward for your heroic accomplishments, {name}.\n\nYou have bought us precious time!", sourceObjectiveStatus = "unverified-source-field" }
quests[14302] = { id = 14302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Official Assessment", description = "You have accomplished much in your efforts against the naga, {name}. But I fear it is not nearly enough....\n\nThis is my official assessment of the naga presence.\n\nI'm confident that my peers in the wildlands will take the necessary action.\n\nBring this to Karnum at the grove in the center of the Cenarion Wildlands to the southeast. He will know what to do.\n\nThank you, {name}. And farewell.", sourceObjective = "Cenarion Researcher Korrah wants you to take Korrah's Report to Karnum at Karnum's Grove.\n\nProvided item:", completion = "<Karnum opens and reads Korrah's Report.>\n\nThis is alarming news, indeed, {race} - something we have no shortage of here.\n\nI shall call a council regarding the issue. You will be summoned if you are needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[14303] = { id = 14303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Aggra", description = "Return to the Horde Base Camp and let Aggra know that we still live, {name}.\n\nTell her that I am moving on to the Wild Overlook and that we will all meet up on the northwest side of the island. I expect to see you there.\n\nWe will track down the Alliance and slay them to the last!", sourceObjective = "Inform Aggra at the Horde Base Camp on the Lost Isles of all that has transpired.", completion = "<Aggra gives you the eye as if she doesn't quite believe what you are telling her.>\n\nI am not easily impressed, but if what you are telling me is true, then I have never before heard of such a thing.\n\nYou have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14304] = { id = 14304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Theory", description = "The land is not all that has changed in Desolace. Here, the wildlife has responded to their new environment in strange and sometimes exciting ways.\n\nI am particularly interested in the Rejuvenated Thunder Lizards that roam just to the west.\n\nI need a sample of their blood.\n\nYou may begin helping me by using this jar of leeches on a few of them.\n\nOnce they've filled on the blood of those beasts, return them to me.", sourceObjective = "Collect 10 Blood-filled Leeches.", progress = "Were you able to recover the samples I require?", completion = "This should be enough.\n\nThank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14305] = { id = 14305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Reap", description = "No one knows better than the Cenarion Circle that this lush oasis could dry up as quickly as it appeared.\n\nWe must take care not to interfere with the processes taking place here, but to support and preserve them,\n\nA new species of plant, very plentiful in the surrounding region, has appeared since the great change.\n\nCollect samples of these for me, that I might study them and learn what they have to teach us,", sourceObjective = "Collect 10 Aloe Thistles.", progress = "Have you collected the samples I require?", completion = "These are fine specimens, {race}.\n\nI shall commence my studies immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[14306] = { id = 14306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pulling Weeds", description = "With such an abrupt change to the ecology, it is to be expected that some of the flora and fauna don't react as well as we'd hope.\n\nThe uprooted lashers are a troublesome example of this. Roaming the fields to the east and south they are a detriment to the region and must be disposed of.\n\nWhile you're about, please deal with any of these pests that you find.", sourceObjective = "Kill 7 Uprooted Lashers.", completion = "On behalf of Desolace herself, I thank you, {race}.\n\nPlease accept our deepest gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[14307] = { id = 14307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stubborn Winds", description = "The winds of change are blowing, {race}. Of that there can be no doubt.\n\nThere are many pressing issues vying for our attention and action. Chief among them is the spreading of our growing oasis.\n\nIts growth has surpassed our hopes as well as our understanding, yet now it faces opposition.\n\nTo the west, where the grass meets the sand, whirlwinds prevent its penetration into the desert.\n\nGo and eliminate this hostile obstacle to life!", sourceObjective = "Destroy 5 Whirlwind Stormwalkers.", completion = "You have done well, {class}.\n\nWe will doubtlessly call upon you for assistance with more significant matters in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[14308] = { id = 14308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Science Attacks", description = "Did you see the explosions on the way in? The Secret Lab is engulfed in flames! Again! If we don't stamp out those flames we're going to hit critical temperatacity and resonate into a meltdown cascade.\n\nHere, I'm entrusting you with a canister of experimental hypercooled pressurized liquigel: The most volatile fire retardant known to science! (Keep that canister away from open flame.) Put out the fires and hose down my interns, then contact me via the squawkbox in central control.", sourceObjective = "Use the Fireliminator X-21 to extinguish 8 fires and to rescue 6 Research Interns from the inferno at the Secret Lab.\n\nSee Assistant Greely at the Southern Rocketway Terminus if you lose your Fireliminator.", progress = "<Greely's squeaky voice peels through a set of speakers.>\n\nRocketway to Secret Lab! Rocketway to Secret Lab! Come in, Secret Lab...", completion = "Nice work, {name}! Now, we need to decouple the reaction core matrix from the fuel sumps, or that whole place is gonna blow itself to Outland...", sourceObjectiveStatus = "unverified-source-field" }
quests[14309] = { id = 14309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Kodo", description = "As you have by now witnessed, the rapid changes to this region can have both positive and negative effects on the native creatures.\n\nTo the south and east of here, enraged kodo are a constant threat to anyone nearby.\n\nIt's time to put my theory to the test. I've used the rejuvenated thunder lizard's blood in the making of this concoction. I'm hoping it will soothe the kodo when they eat it.\n\nPlace it near an enraged kodo and make sure you do it from a safe distance!", sourceObjective = "Use the Kodo Concoction near 5 Enraged Kodos.", completion = "Wonderful! Karnum will be so pleased!\n\nPlease, accept this as my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[14310] = { id = 14310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segmentation Fault: Core Dumped", description = "Once we flush the central reactor, I need you to return the core to me. It's 100% refined azsharite crystal, which is both powerful and dangerous. And lovely. Oh precious azsharite, the shaper of worlds to come!\n\nThe giant lever to your left will dump the core and send it to me via the rail system. The core will be superheated, so you'll need to periodically douse it with the Fireliminator on the way here... don't let it reach critical temperature!", sourceObjective = "Activate the Reactor Control Console and escort the Azsharite Core back to the Southern Rocketway Terminus. Use the Fireliminator X-21 on the Core if it starts to overheat.", progress = "Don't worry about the residual effects of all those burning chemicals in the lab. Hair grows back!", completion = "Whew, the sample is secure. And it's still steaming! Thank you, {name}.\n\nAzsharite is a complex mystery wrapped in a velvety enigma of danger. Grapplehammer insists that we learn more about this strange substance.", sourceObjectiveStatus = "unverified-source-field" }
quests[14311] = { id = 14311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Part", description = "What a glorious time we live in!\n\nThe former wastelands of Desolace are blooming, bursting with life. Imagine, {class}, if all of Azeroth's wastelands awoke in such a fashion! Perhaps someday...\n\nIt's true that there are weighty issues at hand here, but why not take a moment to appreciate the wondrous miracle we are witnessing?\n\nIn fact, why not take part in it? Here are some Cenarion Seeds. Use them at the more fertile spots of the wildlands.\n\nPerfect medicine for lifting a weary soul!", sourceObjective = "Use the Cenarion Seeds next to 5 of the Fertile Mounds around the Cenarion Wildlands.", completion = "The rejuvenation is so invigorating! Don't you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[14312] = { id = 14312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Introduction Is In Order", description = "I have heard of your exploits here in Desolace, {name}. We are in your debt.\n\nI'm afraid I must involve you in yet another crisis, one more pressing than the rest.\n\nThe landscape is not all that has changed here of late. Old conflicts have made way for new, more dire ones. I should allow our guest to explain further....\n\nKhan Leh'prah is among the last of the Kolkar tribe that once possessed all of eastern Desolace. We found him near death on our borders. Listen to his words.", sourceObjective = "Garren Darkwind at Karnum's Glade wants you to speak to Khan Leh'prah.", completion = "Be not afraid, {race}. I mean you no harm.", sourceObjectiveStatus = "unverified-source-field" }
quests[14313] = { id = 14313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Among Humans Again", description = "So Krennan's potion did not kill you?  Well, I suppose that means the human inside of you is in control then.\n\nI guess I won't be shooting you after all.  At least not yet.\n\nGo speak to Krennan Aranas and give him the good news.  He's in charge of the house where we keep... your kind.\n\nJust remember, {name}.  I've got my eye on you.  You so much as try anything funny and you'll get a bullet between the eyes.", sourceObjective = "Speak to Krennan Aranas in Duskhaven.", completion = "It worked!  By the Light, it worked!", sourceObjectiveStatus = "unverified-source-field" }
quests[14314] = { id = 14314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breakout!", description = "It began with a dream that repeatedly warned me of the danger to come. I saw the demonic legions bearing down upon our kind, overrunning our lands.\n\nThe dream has become real. The Burning Blade and their demon masters have pushed the Magram out of their lands in the south. In turn, the Magram have defeated my people and taken over our homes.\n\nThe fight was ferocious. Only a handful of the Kolkar still live. I would ask that you visit what was once my land in the east, and free them from their prison.", sourceObjective = "Kill the Magram Warden at the Magram Village.", progress = "Have my people been freed, {race}?", completion = "I thank you, {race}.\n\nOur tribe may not have survived without your aid.", sourceObjectiveStatus = "unverified-source-field" }
quests[14316] = { id = 14316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Property", description = "Since the demons have invaded their lands, the Magram have broken all ties with any outsiders.\n\nThey are untrusting and hostile and have taken to stealing from others instead of providing for themselves.\n\nMany of our needed supplies have gone missing of late and we suspect that the Magram are to blame.\n\nPlease, {name}, go to their lands in the east and search for our belongings.", sourceObjective = "Collect 7 Cenarion Supply Crates from the Magram Lands.", progress = "Were you able to find our belongings, {name}?", completion = "As we suspected, the Magram have been stealing our supplies.\n\nWe shall guard them more closely.", sourceObjectiveStatus = "unverified-source-field" }
quests[14318] = { id = 14318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delicate Negotiations", description = "There is but one way to win the trust and loyalty of the Magram.\n\nIt must be beaten out of them.\n\nThey have suffered many losses in their war against my clan. They now possess an unfamiliar land, where they struggle just to feed themselves.\n\nNow is the time to strike.\n\nSpeak to me when you are ready, then ride in and plant my spear in the Fatherstone. If we can kill enough of them, their Khan will submit to our will.", sourceObjective = "Khan Leh'prah wants you to place the Spear of the Kolkar Khan in the Fatherstone and defend it from the Magram until Khan Kammah appears.\n\nSpeak to Khan Leh'prah when you are ready to ride to the battle site.", progress = "What do you want?", completion = "Why is it that you meddle in centaur affairs, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[14320] = { id = 14320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Need of Ingredients", description = "Ah, yes.  The effects of the Curse cannot ever be fully cured as far as we know.\n\nWith treatment, however, your mind will remain yours... and not that of a wild animal.\n\nWe are fortunate that the treatment worked on you.  Normally, I can only treat recent infections.\n\nWe'll need to continue your medication if we're to have you reverse the Curse.\n\nI will need mandrake essence to brew another batch of my serum for you.  You will find a crate stashed beneath a shed southwest of town.", sourceObjective = "Find the Crate of Mandrake Essence.", completion = "The crate has been smashed and the vials inside of it appear to have been broken.", sourceObjectiveStatus = "unverified-source-field" }
quests[14321] = { id = 14321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion", description = "<A long knife with a skull ornament on its hilt sticks out of the militiaman's ribs.  As you look around for clues, you spot a pair of savage-looking warships at the shore.>\n\n<Gilneas is being invaded.  Bring word back to Duskhaven's Mayor, Gwen Armstead.>", sourceObjective = "Speak to Gwen Armstead in Duskhaven.", completion = "Forsaken!  Quick, {name}!  We must mount a defense.", sourceObjectiveStatus = "unverified-source-field" }
quests[14322] = { id = 14322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Science! Bad!", description = "I was trying to domesticate the indigenous hippogryphs here using a series of debilitating electrical shocks, when for some reason they went berserk! Now my test subjects are tearing up this place for no good reason! {class}, go slaughter my failed experiments before they find me.", sourceObjective = "Kill 8 Static-Charged Hippogryphs.", progress = "Are they dead? Is it safe to go outside again?", completion = "So the world is safe for science again? Excellent! Next time I'll try heated needles or something.", sourceObjectiveStatus = "unverified-source-field" }
quests[14323] = { id = 14323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absorbent", description = "One other thing I need. Hot water.\n\nNot easy around here. Not hot springs, no friends to share. One good way though. Have this sponge... it's ultra absorbent! Use it to go soak Vile Splashes at the sandbar eastish.\n\nWith enough, go squeeze them out over near the tower to summon jumbo elemental. He has hot water.", sourceObjective = "Collect 20 Simmering Water Droplets from the Vile Splashes east of the Ruins of Arkkoran.", progress = "The Azshari Sea Sponge undulates with living water.", completion = "You've collected all of the simmering water droplets that Ergll requested. Now it's just a matter of summoning the \"jumbo\" elemental.", sourceObjectiveStatus = "unverified-source-field" }
quests[14324] = { id = 14324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full of Hot Water", description = "Ergll indicated that you should be able to use the Engorged Azshara Sea Sponge to summon a \"jumbo\" elemental near the Tower of Eldara to the northeast.", sourceObjective = "Obtain a Globe of Boiling Water from a Scalding Water Lord at the Tower of Eldara.", progress = "You're back!", completion = "Convenient, no? Who needs hot springs anyway. This is perfect.", sourceObjectiveStatus = "unverified-source-field" }
quests[14325] = { id = 14325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will Work For Food", description = "<Khan Kammah listens as you explain the demonic threat, and Khan Leh'prah's visions.>\n\nNo one need lecture us about the demons, {race}. It is they who drove our clan from our ancestral lands.\n\nIt is they who forced us to take over the Kolkar wastelands, where we struggle just to exist.\n\nThe war against the Kolkar took a heavy toll on my people. What few of us remain are weary and hungry.\n\nBring food for my people and then we shall discuss the demons.", sourceObjective = "Collect 5 Basilisk Flanks.", progress = "Have you brought food for my clan, {race}?", completion = "Very good, {race}.\n\nThis will sustain us for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[14326] = { id = 14326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me Up Top", description = "I never thought that I would be a prisoner of the Alliance again. I cannot begin to express my gratitude to you... {name}, is it?\n\nI will meet you up top and from there we will deal with them.", sourceObjective = "Make your way up top on the upper deck of the Vengeance Wake off the shore of the Lost Isles and speak with Thrall.", completion = "My mission is too critical to let these meddlers continue to dog us. It's up to you and I to put an end to this once and for all!", sourceObjectiveStatus = "unverified-source-field" }
quests[14327] = { id = 14327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Word is My Bond", description = "It would seem that we have no choice.\n\nAs reluctant as I am to cooperate with the Kolkar, there is wisdom in the words of their Khan.\n\nYou may give him my word that we shall lend our spears to the battle.", sourceObjective = "Khan Kammah wants you to speak to Khan Leh'prah.", completion = "You have done well, {class}.\n\nNow we must convince the Gelkis...", sourceObjectiveStatus = "unverified-source-field" }
quests[14328] = { id = 14328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Princes", description = "The Gelkis reside in southwest Desolace. They are just as stubborn as the Magram, and since they have not suffered war and relocation, they are considerably stronger.\n\nHumbling the Gelkis will require an extreme show of force.\n\nKhan Shodo and his three sons rule the clan. Shodo is aging, and suffers from old war wounds. He never leaves the depths of his cave. The strength of his rule lies in his sons.\n\nSlay them, and persuade the Khan to commit to our cause.", sourceObjective = "Slay Rhoho, Sherik, and Jorreth.", completion = "My sons all slain... my clan in ruins....\n\nWere I in my youth, I would tear you limb from limb!\n\nGo now... kill me or leave me to mourn alone, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14329] = { id = 14329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not So Fast!", description = "<The Khan of the Gelkis clan stares at you with an empty gaze as you detail the demon threat and Leh'prah's visions.>\n\nIt matters not to me what becomes of this land now. I have failed my clan and my forefathers....\n\nThere is but one thing left in this world that might bring my old soul hope, and she's likely dead as well.\n\nMy precious daughter, Kherrah, was taken from me by the Maraudine clan. If you can bring her back to me alive, I shall consider your proposal.", sourceObjective = "Khan Shodo wants you to kill 10 Maraudine Maulers in the Valley of Spears.\n\nYou are to search their corpses for clues to Kherrah's whereabouts.", completion = "As you slaughter their enemy, the Gelkis clan cannot help but to acknowledge your prowess.", sourceObjectiveStatus = "unverified-source-field" }
quests[14330] = { id = 14330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Closed Doors", description = "You've discovered the location of Khan Shodo's daughter, Kherrah. She is being held behind the doors to Maraudon!\n\nThe rescue attempt is certain to be risky, but if you seek the Gelkis clan's cooperation, you must free the Khan's daughter.", sourceObjective = "You are to find Kherrah somewhere behind the doors to Maraudon.\n\nProvided item:", completion = "Is it safe for me to leave, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[14332] = { id = 14332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time For Change", description = "<Kherrah listens to you as you explain recent events.>\n\nI agree with the words of the Kolkar Khan. The time for ancient grudges is over. It is a shame that it has taken a demonic crisis to unite the tribes.\n\nI shall return to my father and convince him to join your cause. You have my word that he will comply.\n\nReturn to Khan Leh'prah and inform him that the Gelkis will be ready when called upon.", sourceObjective = "Kherrah wants you to speak with Khan Leh'prah.", completion = "You have done well, {race}.\n\nAnd not a moment too soon....", sourceObjectiveStatus = "unverified-source-field" }
quests[14333] = { id = 14333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While You're Here", description = "The Maraudine have raided the Gelkis camps for many years, stealing anything they could get their hands on.\n\nOne of their favorite torments is to take these relics of power which the Gelkis hold sacred, and bring them here to be defiled.\n\nThe Gelkis clan would certainly be grateful if you were to find and destroy these defiled artifacts.", sourceObjective = "You are to scour the Valley of Spears to find 6 Defiled Relics.", completion = "The destruction of those defiled relics will ease the minds of the Gelkis, and will strengthen their resolve.\n\nYou have done well.", sourceObjectiveStatus = "unverified-source-field" }
quests[14334] = { id = 14334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blubbergut", description = "Ahoy, mon!\n\nYou think you be able ta do something for da village here?\n\nMost whales we can handle fine, but there be a special whale out there that be too big for our spears.\n\nBlubbergut been gettin' bigger an' bigger - eatin' up the fish we use to live on!\n\nGet out there and find the thing, then make him pay for his gluttony!", sourceObjective = "Mai'Lahii wants you to kill Blubbergut.", completion = "Oy, mon! Ya did it!\n\nWe soon be havin' fish to eat, thanks be to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[14335] = { id = 14335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chipping In", description = "As you have no doubt noticed by now, the recent changes to the land have had many side-effects. Some of these are beneficial, while others pose serious problems.\n\nJust south of the village the local lobstrok are emerging from the sea and choking off the road to the village.\n\nPlease, {class}, go and thin the numbers of this pest.", sourceObjective = "Kill 5 Drysnap Crawlers and 5 Drysnap Pincers.", completion = "On behalf of us all at Shadowprey Village, I thank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14336] = { id = 14336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill or Be Killed", description = "The reefs have always protected us from a coastal attack.  The earthquakes must've opened a passage for the Forsaken ships.\n\nQuick, {name}.  Slow down the attackers while I get the rest of the militia ready.\n\nI think I can hear the Prince and some of our men engaging the Forsaken even as we speak.  Speak to Liam and see how you can be of use.\n\nOh... and make sure he doesn't get himself killed.  I'm afraid he might be a little reckless in his current state.", sourceObjective = "Speak to Prince Liam Greymane outside of Duskhaven.", completion = "{name}!!!  You ARE alive!\n\nI thought I was having dreams about the old days when I heard your voice...", sourceObjectiveStatus = "unverified-source-field" }
quests[14337] = { id = 14337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowprey Village", description = "Hello again, {class}.\n\nI have received news that Shadowprey Village is in need of some assistance. Our hands are more than full here, so I must call upon you to travel there and be of assistance to them.\n\nThe village lies on the coast to the southwest of here. When you arrive, seek out the one named Mai'Lahii.", sourceObjective = "Karnum Marshweaver wants you to speak with Mai'Lahii.", completion = "Welcome to Shadowprey Village, {race}.\n\nI was not sure the Cenarion Circle would send anyone.", sourceObjectiveStatus = "unverified-source-field" }
quests[14338] = { id = 14338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost Walker Post", description = "Greetings, {class}.\n\nIt is good to see that you still draw breath. The time has come for me to call upon your services.\n\nJust southwest of this glade stands Ghost Walker Post. There you will find a forsaken by the name of Maurin Bonesplitter.\n\nHe may have a solution for one of the problems we face here.\n\nSpeak with him and do what you can to assist him.", sourceObjective = "Karnum Marshweaver wants you to speak with Maurin Bonesplitter.", completion = "Greetings, {class}.\n\nIt is good that you have finally arrived....", sourceObjectiveStatus = "unverified-source-field" }
quests[14339] = { id = 14339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery Device", description = "As fate would have it, there's a special deed that needs doing - one that will benefit the Cenarion Circle as well as myself.\n\nYou see, {class}, I am under pressure to create a special... concoction, shall we say. I believe my work to be complete, but I need to have it tested to be certain.\n\nThe target of this test is to be the naga, who threaten this region from the west. Their demise would surely aid the Circle.\n\nFirst though, I need a delivery device. Hollow horns from the dying kodo should do nicely.", sourceObjective = "Maurin Bonesplitter wants you to collect 3 Hollow Kodo Horns from Dying Kodo.", progress = "Back so soon, {class}?", completion = "Yes, yes.\n\nThese will do nicely....", sourceObjectiveStatus = "unverified-source-field" }
quests[14340] = { id = 14340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dressed to Impress", description = "Every man's got to learn his own lessons I suppose.\n\nHere, take my wizard hat. I have no doubt that he'll take you on as an apprentice if you look the role... you just might have to jump through some hoops first. Tiny flaming hoops, suspended over spikes, with spinning blades on the other side.\n\nYou should be able to find an image of Xylem on top of that hill to the northeast.", sourceObjective = "Put on your new wizard hat and then speak to the Image of Archmage Xylem just northeast of the Northern Rocketway Exchange.", progress = "Hello.", completion = "Well look at you, aren't you just a marvel of modern Magery! Quite a fancy hat, I must say.\n\nApprentices. Apprentici? I do think that I might have quite a few already, but I suppose one can never have too many appren..tici.", sourceObjectiveStatus = "unverified-source-field" }
quests[14341] = { id = 14341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smeed's Harnesses", description = "Pardon me, young {race}.\n\nI'm in need of a little help. I've just finished filling an order for harnesses that must be delivered right away.\n\nI'm a bit old for the trip, especially considering how dangerous things have become lately.\n\nWould you mind?\n\nThey need to go to Smeed, a goblin who lives just southeast of here.", sourceObjective = "Nataka at Ghost Walker Post wants you to deliver Smeed's Harnesses to Smeed.\n\nProvided item:", completion = "Ahh, my harnesses!\n\nThanks, friend!", sourceObjectiveStatus = "unverified-source-field" }
quests[14342] = { id = 14342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Encroachment", description = "The demons are on the move, {race}!\n\nIf nothing is done, we'll be overrun in a matter of weeks. I've just returned from Mannoroc Coven, where the infernals there are falling from the sky!\n\nWe need to at least buy ourselves some time. Get down there and pick up where I left off!", sourceObjective = "Felgur Twocuts wants you to destroy 10 Lesser Infernals.", completion = "Well done, {race}!\n\nThe danger persists, but you have bought us some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[14343] = { id = 14343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maurin's Concoction", description = "<Maurin carefully seals his concoction into the hollow kodo horns.>\n\nHere you are, {class}.\n\nBring these to Karnum. It's up to him how he wants to use them on the naga. \n\nI'll be watching to gauge the effectiveness of my formula!", sourceObjective = "Maurin wants you to deliver Maurin's Concoction to Karnum at Karnum's Grove.\n\nProvided item:", completion = "I hate to use such unnatural measures, but I fear we simply have no choice....", sourceObjectiveStatus = "unverified-source-field" }
quests[14344] = { id = 14344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugkar's Undoing", description = "You recognize this as the essence of a summoned demon.\n\nDangerous and rarely understood energies weave in and out of its surface.\n\nAs you gaze upon it, a vision fills your mind - an image of yourself controlling demonic minions. A rush of excitement flows through you as you imagine wielding such power.\n\nLooking at your surroundings, you wonder how this treasure might be used against this demonic enemy....", sourceObjective = "You are to use the Infernal Power Core to take control of Lord Azrethoc at Jugkar's Altar, and use its powers to slay Jugkar Grim'rod.", sourceObjectiveStatus = "unverified-source-field" }
quests[14345] = { id = 14345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wash Out", description = "Delicious!\n\nAzy always trying to get his hands on magic artifacts. Said he was trying to make friends with that archmage person. Xylem!\n\nXylem has LOTS of apprentices. Takes in all kinds, burns'm out, leaves them wandering all over. High turnover.\n\nLast one was last night. Headed over towards that big goblin tower construction thing, way west. Maybe he'll help you meet Xylem? Maybe Xylem knows where Azy is?\n\nPlay nice!", sourceObjective = "Speak to Sorata Firespinner at the Northern Rocketway Exchange.", completion = "Look buddy, I was in your shoes not a week ago. Big powerful Archmage actually takes on apprentices! Who could pass up an opportunity like that?!\n\nSometimes, things really are just too good to be true.", sourceObjectiveStatus = "unverified-source-field" }
quests[14346] = { id = 14346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Our Crevasse", description = "As you of course know, {name}, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!\n\nWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault. Once there, use Maurin's Concoction to teach them a lesson they shall not soon forget.", sourceObjective = "Karnum Marshweaver wants you to use Maurin's Concoction to kill 10 Slitherblade Invaders, 10 Slitherblade Sirens, and 3 Sea Giants.", progress = "Have you dealt with the naga in our crevasse, {name}?", completion = "Your deeds continue to impress me, {name}.\n\nPlease accept this gift on behalf of the Cenarion Circle.", sourceObjectiveStatus = "unverified-source-field" }
quests[14347] = { id = 14347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold the Line", description = "{name}!  I'm still not sure if you're alive or dead... human or worgen...\n\nI'm not even sure if I'm really awake.  But THIS I am sure of...\n\nWe're going to kill a great many of these motherless Forsaken.", sourceObjective = "Kill 10 Forsaken Invaders.", completion = "Yes, {name}!  Just like old times...\n\nI'm going to have to work hard at not shooting you, but Krennan explained everything to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14348] = { id = 14348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Can't Take 'Em Alone", description = "Look here, {name}.  The big fat ones -- abominations, they're called -- they don't go down easy, so don't tackle them on your own.\n\nBut I have an idea so crazy it might just work.  Or it might get you killed, if we're not careful, I suppose.\n\nThere's barrels of gunpowder beneath the sheds and by the windmills.  Grab them and toss 'em right on the abominations' heads.  I'll take care of the rest with this trusty old blunderbuss.", sourceObjective = "Use the Black Gunpowder Kegs to blow up 4 Horrid Abominations.", progress = "They just keep coming, don't they?", completion = "You and me, {name}.  We make a great team...\n\nIt's good to have you back.", sourceObjectiveStatus = "unverified-source-field" }
quests[14349] = { id = 14349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call to Command", description = "The order has come down, {class}. Sylvanas herself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to the Dark Lady. Do not embarrass me, {class}!", sourceObjective = "Travel to the Undercity and speak with Lady Sylvanas Windrunner.", completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into our lands, desecrate our structures and monuments and murder our people.\n\nThe time has come to deal with this pest. You will become the instrument of our reckoning.", sourceObjectiveStatus = "unverified-source-field" }
quests[14350] = { id = 14350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crimson Courier", description = "We cannot attack the Scarlet Crusade's command directly; they are too well defended. But there's more than one way to skin a cat. They'll be nothing without their main force.\n\nThe Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, {race}! Find the Crimson Courier and recover that report. Bring it to Nathanos.", sourceObjective = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.", progress = "Succeed now and you will have almost earned my respect, {class}.", completion = "<Nathanos laughs.>\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!", sourceObjectiveStatus = "unverified-source-field" }
quests[14351] = { id = 14351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Hillsbrad", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Bragor Bloodfist in the Undercity.  Go with pride, {class}.", sourceObjective = "Take Darthalia's Sealed Commendation to Bragor Bloodfist in the Undercity.", progress = "Why aren't you out on the battlefield, {class}?", completion = "So you're the {class} who tore through the Alliance forces in the Hillsbrad Foothills? I've heard your name already. Word travels fast.\n\nThe Horde can use someone like you if you keep this up, {name}.\n\nWe need to keep our eyes on all threats around us, but with that king leading them, the humans will continue to be a problem. You've confirmed that there's strength enough in the Horde to end that threat in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[14352] = { id = 14352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unholy Alliance", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", sourceObjective = "Take the Small Scroll to Bragor Bloodfist in the Undercity.", progress = "What do you want, {name}? This had better be important.", completion = "I've seen the insignia on this scroll before during my time in Northrend. You say this was on that crone who leads the pigs in Razorfen Kraul?\n\nI'll be damned if I'm going to let the Scourge get a foothold here. The one who wrote this - this Malcin - is one of the Lich King's servants, obviously, and that makes him a target. Your target.\n\nThey're not going to take Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[14353] = { id = 14353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unholy Alliance", description = "Supposedly this Malcin is outside Razorfen Downs. There's no question - he has to die.\n\nMy contacts in Orgrimmar tell me their scouts have found signs of the Plague down there. The quilboar are showing signs of being plagued, too; they're much more powerful. Whatever the Scourge are doing down there needs to end. Now.\n\nFind this Malcin and kill him. Report back here when he's dead.", sourceObjective = "Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.", progress = "Did you find the Ambassador, {name}? Did you kill him?\n\nI will not have the Scourge gain a foothold in Kalimdor. We've fought too hard to allow them easy access to our cities.\n\nAt least their crone still numbers among the living. She might be stupid enough to allow the Scourge in her home, but she must have sense enough to know she'd lose everything if she took the 'power' they offer.", completion = "Good work, {class}!\n\nYou've done the Horde proud by stopping the Scourge from setting down roots on our soil. An act like that deserves a reward, and the Forsaken have enough lying around that I'm sure they can spare a few things.\n\nWe may not know everything they've done in the Downs, but we'll find out. They can't slink around in the dark forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[14354] = { id = 14354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Gifts", description = "Simply intolerable!\n\nSatyrs of all things, desecrating our sacred lands...\n\nTheir days are numbered, {race}. I can assure you of that. As soon as we have the numbers, I shall lead a charge that will rid this land of the wicked creatures.\n\nFor now, though, perhaps you could put my mind at ease?\n\nTravel just east of here to Sargeron and scour the ruins. Find the relics of Elune and ensure that they are in good condition.\n\nI'll pay you well for this favor.", sourceObjective = "Visit Elune's Relics in Sargeron.", completion = "The relics are intact! Well, indeed, that is something.\n\nYou have put my mind at ease, {race}. Please accept this as my gift to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[14355] = { id = 14355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Scarlet Monastery", description = "One of my duties while I'm stationed here is to help the Forsaken take care of their borders, and that, {class}, is exactly what you're going to do for me.\n\nI might live and breathe, but the Scarlet Crusade will cut down my people as quickly as they will one of the undead. They're a problem here, a big one, and you're going to do something about it.\n\nGo to the Monastery and slay High Inquisitor Whitemane and her lieutenants.", sourceObjective = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Bragor Bloodfist in the Undercity.", completion = "I'm sure Sylvanas will be glad to have that problem taken care of, {name}. The task I gave you wasn't easy, but here you stand, victorious. That commands respect, and what you've done won't be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14356] = { id = 14356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power to Destroy...", description = "Listen up, {class}.\n\nYou may not know this, but Orgrimmar's got a problem. Deep in Ragefire Chasm, a sect of the Shadow Council called the Searing Blade performs their sinister work. They're mainly orcs, and I can't trust sensitive information in the hands of the grunts there. That's where you come in.\n\nThey should have two books in their possession. I want them kept out of the hands of the Searing Blade and the Forsaken alike. Bring them to me directly.", sourceObjective = "Bring the books Spells of Shadow and Incantations from the Nether to Bragor Bloodfist in Undercity.", progress = "Did you secure the books? They need to be kept out of the wrong hands.", completion = "Good, {class}. You've done well. I'll keep these safe from prying eyes; the last thing we need is a strong Shadow Council rising up again.\n\nCheck back with me in the future; there's always something that needs doing around here, apparently, and I might need another able body.", sourceObjectiveStatus = "unverified-source-field" }
quests[14357] = { id = 14357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Hilt!", description = "The handmaiden of Elune! It's even more glorious than the stories tell.\n\nThe legends surrounding this relic come to your mind as you draw near it:\n\nIn ancient time, after battle, the enemies' weapons were to be cast upon the basin in exchange for a divine gift of some sort.\n\nAs you ponder this ritual, the glint of steel catches your eye from a nearby weapon rack....", sourceObjective = "Collect 20 Satyr Sabers from the weapon racks and various satyrs in the region.", progress = "The statue stands expectantly.", completion = "With the ritual completed, you are awarded a divine gift.\n\nYou can't help but to feel a great sense of honor as you receive one of Elune's boons.", sourceObjectiveStatus = "unverified-source-field" }
quests[14358] = { id = 14358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Pounds of Flesh", description = "According to ancient legend, this ancient brazier was placed here for the performing of sacrifices.\n\nFrom what little you remember of the stories, a blessing is bestowed upon the being who places the flesh of Elune's enemies on the brazier's burning embers.\n\nLooking around, you determine that the satyrs who now possess this region would likely qualify.", sourceObjective = "Collect 10 pieces of Satyr Flesh from the various satyrs in Sargeron.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier graciously endows you with a blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14359] = { id = 14359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings From Above", description = "You feel a deep connection to the distant past having partaken of the ancient blessing granted by this relic.\n\nYou determine to make as much as you can of this divine gift.", sourceObjective = "You are to collect 10 pieces of Satyr Flesh from the various Satyrs in Sargeron, and place them on Elune's Brazier.", progress = "The brazier silently awaits an offering.", completion = "The divine brazier graciously endows you with a blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14360] = { id = 14360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing a Couple of Melons Won't Fix", description = "The markings on the Sargeron ruins, combined with what you've gleaned from Furien's text make one thing clear:\n\nThere is something special about the old fountain in the Sanctuary of Elune.\n\nIt would seem that one could expect special power from washing their face in the fountain. First, of course, there would need to be something in the ancient fountain with which to wash.\n\nPondering this problem, you spot a melonfruit at the base of a nearby tree....", sourceObjective = "You must gather 8 Melonfruit and squeeze their juices into the Cup of Elune at Sargeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[14361] = { id = 14361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace of Mind", description = "We are a forward post, charged with monitoring potential adversaries. Once the Alliance launches its Desolace campaign, our work here will ensure that there are no surprises.\n\nRecently, one of our scouts was caught and sacrificed by the Burning Blade at their stronghold to the west. Since then, we've been assaulted with threats and taunts from a Burning Blade wretch named Kohor.\n\nTheir days here are numbered, but I will pay handsomely for that one to be silenced now!", sourceObjective = "Kill Kohor.", completion = "It is done.\n\nCaptain Pentigast should be able to sleep in peace now that Kohor's threats have been silenced.", sourceObjectiveStatus = "unverified-source-field" }
quests[14362] = { id = 14362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears Are Burning", description = "Captain Pentigast has made no secret of his disdain for the Burning Blade at Thunder Axe Fortress.\n\nSurely, proof of their demise would be of value to him.", sourceObjective = "Collect 25 Burning Blade Ears.", progress = "What have you there, {class}?", completion = "Ears of the Burning Blade?\n\n<Captain Pentigast smiles.>\n\nWell done, {class}. This is just a shadow of what will soon become of that vile cult!", sourceObjectiveStatus = "unverified-source-field" }
quests[14363] = { id = 14363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You'll Know It When You See It", description = "With his dying breath, Kohor mentioned the summoning of a demon that could threaten the entire region.\n\nHe may have been bluffing, but that's not a chance worth taking.\n\nThis cannot wait for the Alliance's invasion of Desolace to take shape. You must scour Thunder Axe Fortress for clues and bring an end to this potential threat.", sourceObjective = "Find the Ancient Summoning Ritual in Thunder Axe Fortress.", progress = "The Burning Blade must not be allowed to succeed with their plan!", completion = "It is most fortunate that you took the time to search for this.\n\nNo one would have expected the Burning Blade to be in possession of something so powerful!", sourceObjectiveStatus = "unverified-source-field" }
quests[14364] = { id = 14364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Their Heads Together", description = "So it's true....\n\nThe parchment you discovered in Thunder Axe Fortress details a powerful summoning ritual. One stronger than the Burning Blade have ever been known to possess.\n\nClearly, this rite must be stopped at all costs!\n\nPerhaps if this demon were summoned forth prematurely the crisis could be averted.", sourceObjective = "Collect 100 Bleached Skulls from Thunder Axe Fortress, then place them at the Burning Blade Summoning Circle, then kill Nazargen.", completion = "You diverted what would have been a serious crisis, {class}.\n\nIf that summoning was delayed just a bit longer, the demon would have become far too powerful for our small forces here to contend with.\n\nPlease accept this gift as our thanks for your service.", sourceObjectiveStatus = "unverified-source-field" }
quests[14365] = { id = 14365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethel Rethor", description = "We have recently received a plea for help from a researcher of the Cenarion Circle.\n\nWe have no one we can spare to send, so I ask that you pay her a visit on our behalf.\n\nKorrah is posted near the ruined tower of Ethel Rethor, on the coast to the west.", sourceObjective = "Corporal Melkins wants you to speak to Korrah at Ethel Rethor.", completion = "It is good that you have come.\n\nThere is grave danger looming here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14366] = { id = 14366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding Steady", description = "We can take it from here, {name}.  Check in with Mayor Armstead.\n\nThese are only a small part of the Forsaken's forces.  If we don't move quickly we're going to have bigger problems on our hands.\n\nSee what you can do to engage the Forsaken army at their landing location.", sourceObjective = "Speak to Gwen Armstead in Duskhaven.", completion = "Great news, {name}.  I've sent the remaining militia to the shore to meet the Forsaken force head on.", sourceObjectiveStatus = "unverified-source-field" }
quests[14367] = { id = 14367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Allens' Storm Cellar", description = "Lord Godfrey is leading the attack near the Forsaken's landing area.  See what you can do to help us keep the Forsaken back.\n\nI've been told Godfrey has commandeered the storm cellar in the Allen Farmstead, far to the west.  Seek him there.", sourceObjective = "Speak to Lord Godfrey inside the storm cellar of the Allen Farmstead in Gilneas.", completion = "The Forsaken are here in full strength, {name}.  We barely have enough men to hold them back.", sourceObjectiveStatus = "unverified-source-field" }
quests[14368] = { id = 14368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Children!", description = "The military will not allow me outside the cellar, but my children are still in my farm!  Please, you must go find them.\n\nThe Forsaken have no regard for innocent life -- my kids are in great danger!\n\nTheir names are Cynthia, Ashley and James.  If you find them, bring them back here.  I'll be forever in your debt.", sourceObjective = "Rescue Cynthia, Ashley and James in the Hammond Farmstead.", completion = "My children are safe!  You've done a wonderful thing, {name}.  I don't know how to thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[14369] = { id = 14369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Beast", description = "I'm not going to lie, {name}.  I don't like the idea of having worgen among our ranks.\n\nWho knows how long 'til Krennan's concoction wears off and you're trying to chomp one of our heads off.\n\nUntil that time, however, we can make ample use of your ferocity.\n\nI want you to go out in the battlefield and kill as many of those Forsaken as you can, in as brutal a way as you can.\n\nWe're going to put the fear of the worgen in them, {name}.", sourceObjective = "Kill 8 Forsaken Footsoldiers or Sailors.", completion = "Not bad, {name}.  It's a good thing you're on our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[14370] = { id = 14370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Azsharite", description = "Azsharite! This mysterious crystalline substance has been used to forge weapons of fel power, but in our hands, we've discovered that it's capable of focusing enormous amounts of energy. It may be the biggest goblin discovery since kaja'mite.\n\nBut what is it? Where does it come from? Why is it located only here? Science demands an answer! I need more samples to study. Search out Azsharite deposits all along the nearby cliffs.", sourceObjective = "Collect 5 Azsharite Samples from the nearby cliffs.", progress = "Have you got more samples? Careless adventurers have been looting this stuff for years - they don't know how precious it is!", completion = "Ah, excellent. Some of these samples look fresh. I'm going to be up to my neck in this stuff trying to solve this mystery!", sourceObjectiveStatus = "unverified-source-field" }
quests[14371] = { id = 14371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gigantic Snack", description = "While you're here running around the cliffs, perhaps you can help me with another line of investigation. The giants who walk these cliffs have been here since these mountains formed. Maybe they know where the Azsharite comes from? It's in our best interest to befriend these giants and find out.\n\nGather up a gigantic meal for me as a peace offering! Kill the mistwing cliffdwellers that have been such a nuisance to our studies and collect their carcasses for me.", sourceObjective = "Collect 8 Mutilated Mistwing Carcasses from Mistwing Cliffdwellers.", progress = "I probably should've warned you that mistwing chimaeras can shoot lightning.", completion = "Phew! The stench! Well, hopefully that massive heap of carcasses smells more appetizing to a giant.", sourceObjectiveStatus = "unverified-source-field" }
quests[14372] = { id = 14372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thargad's Camp", description = "It pleases me to see that you still draw breath, {class}. I have been sent word that the demon activity in the south has been intensifying.\n\nThere is a camp on the borderlands there that is in danger of being cut off if the demons move northward.\n\nPerhaps you could lend them a hand?\n\nI know the leader of the camp there is Thargad. He will be able to direct you wisely.\n\nThank you, friend. Be well.", sourceObjective = "Karnum Marshweaver wants you to speak to Thargad.", completion = "Demons?\n\nOh, there be lots I can tell yeh 'bout demons!", sourceObjectiveStatus = "unverified-source-field" }
quests[14373] = { id = 14373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Encroachment", description = "Listen up, now. An' lookie here.\n\n<Thargad points off to the east.>\n\nYeh see them big green glowin' balls that be fallin' from the sky?\n\nThose be a nasty buncha demons roamin' the lands unchecked. Well, almost unchecked... I've been keepin' 'em on their toes, givin' 'em sumthin' ta think about.\n\nHow 'bout you get over there an' pick up where I left off?", sourceObjective = "Destroy 10 Lesser Infernals.", completion = "Well, lad!\n\nDon't hesitate to knock a few more down for good measure!", sourceObjectiveStatus = "unverified-source-field" }
quests[14374] = { id = 14374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one o' them Burning Blade leaders myself.\n\nPowerful thing! See, yeh use it on demon portals and they just disappear! Spooky magic, but these be desperate times...\n\nThe demons keep comin' at this rate, and my camp will get overrun before ya know it.\n\nHere ya go, now. Get on with it.", sourceObjective = "Banish 6 Portals at Mannoroc Coven.", completion = "Aye, that'll buy us some time, {class}.\n\nThank yeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[14375] = { id = 14375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Chance at Humanity", sourceObjective = "I need you to pull through, {name}.  This dosage is strong enough to kill a horse.\n\nBut I know you.  I know what you're made of.  You will be fine.\n\nTrust me.  I know what you're going through.\n\nNow drink up and close your eyes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14376] = { id = 14376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugkar's Undoing", description = "You recognize this as the essence of a summoned demon.\n\nDangerous and rarely understood energies weave in and out of its surface.\n\nAs you gaze upon it, a vision fills your mind - an image of yourself controlling demonic minions. A rush of excitement flows through you as you imagine wielding such power.\n\nLooking at your surroundings, you wonder how this treasure might be used against this demonic enemy....", sourceObjective = "You are to use the Infernal Power Core to take control of Lord Azrethoc at Jugkar's Altar, and use its powers to slay Jugkar Grim'rod.", completion = "You should be proud of how you manipulated the enemy's power and used it against them.\n\nYou've dealt the demons of Mannoroc a severe blow....", sourceObjectiveStatus = "unverified-source-field" }
quests[14377] = { id = 14377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriending Giants", description = "A cursory study of the azsharite you brought me reveals that it's not biological in nature, nor is it naturally formed. There's another creature in Azshara with similar properties: the cliff giants that lumber around these cliffs.\n\nOne of the giants seems willing to help our research along. Take the meat you collected to Gormungan, the giant standing just west of here. Befriend him, then grill him - find out if he knows the secret of azsharite!", sourceObjective = "Talk to Gormungan outside of the Southern Rocketway Terminus and discover the secret of azsharite.", completion = "Speak slower - what are you saying? Am I hearing you right? Those formations of azsharite are actually where the giants have - oh my. Groady!! Let's not tell Dr. Grapplehammer, he's made this stuff his life's work.\n\nWell, at least now we know where azsharite comes from, and why it's so rare. We've got to figure out a way to speed up, uh, \"production!\"", sourceObjectiveStatus = "unverified-source-field" }
quests[14378] = { id = 14378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Brendol", description = "I'm too busy collectin' artifacts to busy myself with much else, but there is a bit of an issue here I wouldn't mind sortin' out.\n\nThere's a forsaken apothecary who's been pokin' around these parts for a while now. Normally, I'd ignore him, but three times now he's snuck into my camp and pilfered my supplies.... enough's enough!\n\nFind the thief and bring me whatever's left o' my things!", sourceObjective = "Recover Brendol's Satchel.", progress = "Well, {class}? Did yeh find the cretin?", completion = "Justice is done!\n\nNow let's have a peek at what's left of my goods....", sourceObjectiveStatus = "unverified-source-field" }
quests[14379] = { id = 14379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Lobstrock!", description = "Thargad works practically nonstop chasing after ancient Titan relics. He stays so busy that if it weren't for me, he'd probably forget to eat!\n\nSpeaking of eating, I'd like to prepare him something special - perhaps you could help me out?\n\nLobstrock roam all over the coast to the west. I'd never last in a fight with them myself, but I could make a great meal if you were to bring me some of their tails!", sourceObjective = "Get 7 Tender Lobstrock Tails.", progress = "Were you able to collect some lobstrock tails, {race}?", completion = "Ohhh, these will do nicely!\n\nThargad will be so surprised!", sourceObjectiveStatus = "unverified-source-field" }
quests[14380] = { id = 14380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Impactful Discovery", description = "<Thargad rummages through the satchel and pulls out a curious object.>\n\nWell now, this is odd... it's a hollow kodo horn with some sort of potion inside.\n\n<Thargad sniffs the potion.>\n\nWHEW! Definitely not any kind of healthy elixir. This mess is meant for one thing... killin'.\n\nHow 'bout yeh run it back up to Karnum and see if there's anything he can do with it...", sourceObjective = "Take the Mysterious Concoction to Karnum at Karnum's Glade.\n\nProvided item:", completion = "<Karnum examines the concoction.>\n\nYes, {class}. Not only do I know what this is, I know just how you should use it....", sourceObjectiveStatus = "unverified-source-field" }
quests[14381] = { id = 14381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Our Crevasse", description = "I recognize this foul creation. It's a terrible disease that kills almost instantly, and in a most violent manner. Loathe as I am to employ such devices, I fear we have no choice here.\n\nAs you of course know, the naga remain a serious threat to the region. The time has come for us to drive them back into the sea!\n\nWhen you are ready, Grimfeather will take you to the crevasse where they are preparing a violent assault.\n\nUse the concoction on the naga and their allies to make Desolace safe!", sourceObjective = "Use Maurin's Concoction to kill 10 Slitherblade Invaders, 10 Slitherblade Sirens, and 3 Sea Giants.", completion = "Your deeds continue to impress me, {name}.\n\nPlease accept this gift on behalf of the Cenarion Circle.", sourceObjectiveStatus = "unverified-source-field" }
quests[14382] = { id = 14382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two By Sea", description = "The Forsaken catapults are kicking the snot out of us, {name}.  And even if we do take care of them, they've two ships with rows of cannons at the ready.\n\nI've a plan to kill two birds with one stone.  You're the stone in this plan.\n\nTake out the machinists manning the catapults.  After this, use the catapults to launch yourself aboard the Forsaken ships.\n\nIf your aim isn't terrible, you should be able to land safely.  Once onboard, go below decks and take care of each ship's captain.  Good luck, {class}.", sourceObjective = "Use the Forsaken Catapults to board the Forsaken ships and slay Captain Morris and Captain Anson.", completion = "Well done, {name}.  You might be a bloody beast, but you're our beast.", sourceObjectiveStatus = "unverified-source-field" }
quests[14383] = { id = 14383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrible Tinkers of the Ruined Reaches", description = "Scoundrels! Infidels! Ever since I started my operation here in Azshara the Gadgetspring family has hampered my studies and sabotaged my research. And now a mob of middling, second-rate tinkers have rallied to their aid! I have pressing business to attend to: see to it that those gnomes are finished for good.\n\nHead to the Ruined Reaches on the coast, south of my Secret Lab, and start rolling some of their disproportionately enormous heads for me.", sourceObjective = "Slay Bingham Gadgetspring in the Ruined Reaches, along with 4 Netgun Gnomes and 6 Zapper Gnomes.", progress = "I trust you've dug a significant number of tiny graves along the coast, yes?", completion = "Oh - marvelous. Tell me more. And that precocious young Gadgetspring? Dead as well? Ah, wonderful. My work here is important but at times I do miss the carnage of demolishing my enemies on a more personal level. Here, perhaps you can make use of some of my discarded equipment.", sourceObjectiveStatus = "unverified-source-field" }
quests[14384] = { id = 14384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rerouted!", description = "Halt!\n\nOn behalf of the Nijel's Point Guard, I am under orders to send all able-bodied allies to report directly to Corporal Melkins.\n\nI am not authorized to offer any other information.\n\nWhat I can offer is transportation. You are free to use my mount. It will deliver you directly.\n\nDismissed.", sourceObjective = "Officer Jankie wants you to ride her mount to Nijel's Point and speak to Corporal Melkins.", completion = "Welcome to Nijel's Point, {race}.\n\nNow, let's see about getting you briefed on our situation here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14385] = { id = 14385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharite Experiment Number One", description = "Well, I can think of one surefire way to send a giant running to the bathroom, but you're not going to like it. What we need is a ... massive ... laxative. Oh hey! Would you believe the gnomes have something of the sort? That can't be a coincidence. I wonder what they're trying to push through over there?\n\nOur intelligence reports that the laxative was delivered to Gadgetspring's tower, down on the shoreline south of the Secret Lab. Retrieve that laxative and feed it to Gormungan!", sourceObjective = "Grab a giant-sized laxative from the gnomish tower in the Ruined Reaches. Try to feed the laxative to Gormungan the giant.", progress = "Once you have the laxative, try to feed it to Gormungan. And maybe give him a magazine or something. Do it for science!", completion = "So it was a no-go? Literally? Well, Grapplehammer won't take no for an answer. We'll have to try something else.\n\nMaybe I'll have my interns smuggle this laxative into the night elf encampment. That'll be good for a laugh, at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[14386] = { id = 14386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Pack", description = "Excellent work so far, {name}.  Our scouts have identified the leader of the Forsaken ground assault.\n\nOne of Sylvanas' handpicked dark rangers is overseeing the battlefront from the Walden house near the shore.  Take this whistle and use it when you're close to her.\n\nI'll have my men let loose our attack mastiffs to take her down.  Be careful, {name}.  You don't want to engage her alone.", sourceObjective = "Use the Mastiff Whistle to help you slay Dark Ranger Thyala.", completion = "You did it, {name}.  That should take the wind out of their sails.", sourceObjectiveStatus = "unverified-source-field" }
quests[14387] = { id = 14387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lay of the Land", description = "Yes, yes. Welcome to Desolace, {race}.\n\nSorry we had to be so insistent, but we're a small outpost, and there are big problems in this region - most of them quite urgent.\n\nBottom line: We need all the help we can muster.\n\nTo start with, our friend Vahlarriel over there has been getting pretty antsy, insisting that we send a contingent to visit the ruins to the east.\n\nWhy don't you go introduce yourself....", sourceObjective = "Captain Pentigast wants you to speak to Vahlarriel in Nijel's Point.", completion = "A pleasure to meet you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14388] = { id = 14388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharite Experiment Number Two", description = "Okay, new plan. We'll SCARE it out of 'em! In my experience most large creatures are terrified of tiny ones - like rats. Hmm. This place is crawling with rats, but how do we coax them over to the giant?\n\nHey! You don't mind having your cellular matrix broken down and reassembled do you? It's only painful while it's happening. I can shrink you down to rat-sized and you can ride one of these brutes over there like a horse. It's so crazy it's got to work! Speak with me when you're ready for shrinkage...", sourceObjective = "Speak with Assistant Greely to be shrunken down to rat-size. Mount a Rocketway Rat and use it to terrify Gormungan the giant.", progress = "Hey {name}, you look shaken up. Did you scare the giant into going to the bathroom? Or yourself?", completion = "So scaring him didn't work, either? Double-nertz! I'll have to break the news to Grapplehammer: Azsharite's going to remain the rarest substance on the planet. We'll have to use it sparingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[14389] = { id = 14389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasn't It Obvious?", description = "Azuregos! Yes, of course. Troubled old dragon, but lovely heart. I don't think all the years of vagabonds assaulting him have done him much good. He's a mite strange these days.\n\nNot long ago, when returning yet again to our local Spirit Healer, Anara, I couldn't help but notice that her and Azuregos seemed to be hitting it off. I imagine he's still keeping her company.\n\nThe portal behind me is probably the quickest way to reach her. It might sting a little though.", sourceObjective = "Use the portal behind Joanna at Xylem's tower to find Anara the Spirit Healer and--hopefully--Azuregos.", completion = "Azuregos! At last you've found him!", sourceObjectiveStatus = "unverified-source-field" }
quests[14390] = { id = 14390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy is Boring", description = "After a long search with some questionable turns, you've finally found Azuregos.\n\nNow it's just a matter of convincing him to meet up with Kalecgos and put an end to the threat of the black dragonflight in Azshara.", sourceObjective = "Convince Azuregos to return to the world of the living and rendezvous with Kalecgos.", progress = "<Azuregos glares at you.>", completion = "Azuregos has agreed to rendezvous with Kalecgos. Success!", sourceObjectiveStatus = "unverified-source-field" }
quests[14391] = { id = 14391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tables", description = "Azuregos and Kalecgos are due to meet up at the Northern Rocketway Terminus. You should meet with them there to make sure that Kalecgos doesn't require any additional help.\n\nShould you prefer to not be dead, Anara will likely be able to help.", sourceObjective = "Speak to Anara to return to the world of the living, then meet with Kalecgos at the Northern Rocketway Terminus.", completion = "Great to see you again! Thank you for finding Azuregos and sending him to me.\n\nI do feel I owe you an apology - I may have undersold how difficult it would be to accomplish the task I gave you. You performed quite admirably, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14392] = { id = 14392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farewell, Minnow", description = "Thank you, little one.\n\nSometimes it's easy to get lost in the throes of love and lose sight of things, even as a dragon. I plan to rededicate myself entirely to making sure Kalec never steps up to take Malygos' place. It's the most noble cause I can think of.\n\nYou should head back to the harbor. I believe someone's waiting for you there.\n\nTry not to get squashed or eaten by anything.", sourceObjective = "Speak to Sorata Firespinner in Bilgewater Harbor.", completion = "Hey there... again.\n\nLook, I gave you my hat. It was a gift. I thought you'd make some use of it. More specifically though, I thought you'd get it the heck away from me.\n\nCan you imagine my surprise when Xylem comes by himself to give it back to me? \"Want to be more like my other apprentices, Sorata? Give your hat another try.\"  Not one of my proudest moments.\n\nSo what... you just tossed it aside for him to find? No. I don't think so. You're going to take this hat and you're going to like it. Really.", sourceObjectiveStatus = "unverified-source-field" }
quests[14393] = { id = 14393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fray!", description = "For untold generations, the centaur clans have fought against one another, but no more.\n\nBecause of your deeds, we stand here together fighting a common foe. We shall win our ancestral lands back from these demons, or we shall die as brothers.\n\nWhat of you, {name}?\n\nYou have earned the right to fight alongside us. I have a group of my best centaurs for you to lead into battle.\n\nWill you take up the spear?", sourceObjective = "Khan Leh'prah wants you to defeat 15 Burning Blade Warlocks, 3 Doomguard Invaders, and Priestess Than'darissa.\n\nSpeak to Khan Leh'prah to ride into battle.", completion = "Well done, {name}!\n\nLet us finish this!", sourceObjectiveStatus = "unverified-source-field" }
quests[14394] = { id = 14394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Agogridon", description = "Our goal is within sight, {name}!\n\nWe can break the will of this demon army by bringing down the one who leads them. If we can succeed, Desolace will be ours!\n\nWhen you are ready, lead a group of centaurs through the pass to the south, into Shadowbreak Ravine. Find where Agogridon hides!\n\nI will gather the other khans and meet you there to face him in battle.", sourceObjective = "Defeat Agogridon", completion = "Agogridon is no more.\n\nThe demons shall never again take hold in our lands!", sourceObjectiveStatus = "unverified-source-field" }
quests[14395] = { id = 14395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gasping for Breath", description = "{name}!  I was on my way when it happened.\n\nNo time to waste.  A good half of the town watch was in the area that collapsed.  Get in there and save as many as you can.\n\nMake sure to get them out of the water and onto shore.  I'll make sure they get any aid they need.", sourceObjective = "Rescue 4 Drowning Watchmen.", progress = "There aren't many of us left, {name}.  We have to look out for those remaining Gilneans.", completion = "You did what you could, {name}.  With any luck a few others will find their way to shore.", sourceObjectiveStatus = "unverified-source-field" }
quests[14396] = { id = 14396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As the Land Shatters", description = "What in the world was that, {name}?\n\nThose were not cannons or catapults, that is for sure.\n\nGo outside and see what is going on.", sourceObjective = "Speak to Prince Liam Greymane at the Allen Farmstead.", completion = "The ocean, {name}.  It swallowed everything... the land... the Forsaken... our men!", sourceObjectiveStatus = "unverified-source-field" }
quests[14397] = { id = 14397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuation", description = "We've escaped death through dumb luck, {name}.  But luck is running out.\n\nThe coast is becoming flooded even as we speak.  And from the look of it, the landmass beneath us hasn't quite settled yet.\n\nI hate to say this, but we have to leave.  Curses, {name}.... I cannot lose my homeland twice in one lifetime.  Yet these earthquakes are not an enemy we can defeat.\n\nTell Gwen Armstead to start the evacuation.", sourceObjective = "Speak to Gwen Armstead in Duskhaven.", completion = "Liam is right.  We must get everyone to higher ground.\n\nYou must help me spread the word while I manage the logistics of the evacuation.", sourceObjectiveStatus = "unverified-source-field" }
quests[14398] = { id = 14398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma Wahl", description = "It's not going to be easy to get Grandma Wahl to come with us.  You must do whatever you can to convince her, though.\n\nYou'll find her at the Wahl Cottage.  Please, {name}.  Do not lose your patience with her.  Her mind is old and she's not entirely lucid.", sourceObjective = "Find Grandma Wahl at the Wahl Cottage.", completion = "A visitor!  Are you staying for tea, sweetheart?", sourceObjectiveStatus = "unverified-source-field" }
quests[14399] = { id = 14399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma's Lost It Alright", description = "Leave?  Now?\n\nWell, if I must, then I must.  But will you be a sweetheart and find something for me?\n\nI've lost my favorite book and won't leave without it.\n\n<After you explain the gravity of the situation, Grandma Wahl shakes her head condescendingly.>\n\nDear, just find the book will you?", sourceObjective = "Find the Linen-Wrapped Book.", progress = "How goes it, dear?  Will you be staying for tea?", completion = "Why thank you, {name}.  I hope you didn't peek!\n\nWhere are your manners, dear?", sourceObjectiveStatus = "unverified-source-field" }
quests[14400] = { id = 14400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Can't Wear This", description = "What was it you wanted again?\n\nOh, right.  The evacuation orders.\n\nWell I can't be expected to go out in public like this, can I?\n\nGo get me my good clothes.  They're on the clothesline right outside.\n\n<You struggle in vain to convince Grandma Wahl that what she's wearing will do.>\n\nYou young people truly have no manners.  Were you raised by ogres?  Now go get my clothes, sweetie.", sourceObjective = "Get Grandma's Good Clothes.", progress = "Did you find everything okay, dear?", completion = "You're a peach, {name}.  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[14401] = { id = 14401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma's Cat", description = "Right!  About the evacuation, dear.\n\nI just cannot leave without my cat.  He's an adorable orange tabby.\n\nChance's favorite spot to play is a broken down cart near an arbor northeast of here.\n\nBring him here and we'll be on our way.", sourceObjective = "Retrieve Chance the cat.", progress = "You're such a charming young man, {name}.", completion = "There he is!  Grandma's special boy!\n\nThank you so much for finding him.  I hope it wasn't too much trouble.\n\nMy... what manner of dirt found its way underneath my fingernails!", sourceObjectiveStatus = "unverified-source-field" }
quests[14402] = { id = 14402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to Go", description = "I suppose now is as good a time to leave as any.\n\nI have my best outfit, my favorite book and my loving cat.\n\nI hope I'm not forgetting anything.\n\nTell that mayor of yours that I'll be on my way.  I suppose I'll see you in town with the others!", sourceObjective = "Speak to Gwen Armstead in Duskhaven.", completion = "You did the impossible, {name}.  You convinced Grandma Wahl to leave her home.\n\nYou are something else, let me tell you.", sourceObjectiveStatus = "unverified-source-field" }
quests[14403] = { id = 14403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hayward Brothers", description = "The Hayward Fishery can be found far to the south.  The Hayward brothers have been running it for years.\n\nThey don't make it to town very often, except to trade their fish.  Send word to them that the evacuation is underway.", sourceObjective = "Speak to Sebastian Hayward at the Hayward Fishery.", completion = "You here to give us a hand?", sourceObjectiveStatus = "unverified-source-field" }
quests[14404] = { id = 14404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Quite Shipshape", description = "Evacuation, you say?  Well, we had that very same idea all on our own after these Forsaken started showing up.\n\nWe were thinking the water would be the safest way out of here.\n\nUnfortunately our boats didn't come out from that last earthquake unscathed.\n\nI need some additional supplies to finish my repairs: wood, tar and my tools.  Get them for me so that my brothers and I can make it out of here.", sourceObjective = "Obtain Planks of Wood, Coal Tar and Shipwright's Tools.", progress = "Do you have my supplies, {name}?", completion = "This is great, {name}.  I should be able to finish the repairs in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[14405] = { id = 14405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape By Sea", description = "Thanks for your help, {name}.  This ship is ready to sail.\n\nNow you go and tell Miss Armstead that we're not going to be part of the land evacuation.\n\nWe Haywards have been men of the sea for generations.  If we're to leave our home, then we'll do so by sea.", sourceObjective = "Return to Gwen Armstead in Duskhaven.", completion = "It's just as well, {name}.  Maybe the Haywards will fare better than us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14406] = { id = 14406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crowley Orchard", description = "Of course you remember Lord Darius Crowley's daughter, Lorna.\n\nShe never quite recovered after losing her father in Gilneas City.  She's basically led the life of a hermit.  The only visitor she's allowed into her house has been Krennan... and he won't say a word about the whole thing.\n\nSend word to her about the evacuation.", sourceObjective = "Speak to Lorna Crowley at the Crowley Orchard.", completion = "Stay back! Don't make me...\n\nIs it you?  By the Light!  It's you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14407] = { id = 14407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azshara Blues", description = "Hey! I'm glad I caught you.\n\nI come on behalf of my master, Kalec. He requires your aid. Find him under the bridge in the slums as soon as you can!", sourceObjective = "Meet with Kalec in Bilgewater Harbor.", completion = "Thank you for coming. I apologize for the discretion, but it's extremely important that I not be seen by certain individuals.\n\nI'm in quite a bind and I've taken notice of some of your recent deeds. Hear me out, help me, and I'll see to it that you're rewarded in kind.", sourceObjectiveStatus = "unverified-source-field" }
quests[14408] = { id = 14408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nine's Plan", description = "My benefactors used their diminutive intellect to construct an interplanetary transport. As designed, this so-called \"Rocket\" is a death trap. But I suspect a simple re-engineering of the fuel catalyst semifold would render a stable mixture, providing a breathable oxygen byproduct. To implement such changes, I require the original engineering plans.\n\nLocate the Laboratory Archives and ring the doorbell to gain entry. The plans will be held by the lab director himself, presuming he still lives.", sourceObjective = "Acquire the Secret Rocket Plans from the Laboratory Archives building at the eastern end of the Secret Lab. Ring the door buzzer outside and kill the lab director when he emerges.", progress = "I suspect the archives are close, {name}. Locate those plans!", completion = "<The raptor snatches the paperwork in her prehensile claws and holds the schematics up to her face, clucking her pointed teeth dismissively.>\n\nThese are like the scrawling of children. Common sense precludes the routing of control hydraulics so near to the secondary stage burners! Still, this is salvageable.\n\nDo you know how to refactor fuel matrixes for pressure variations at a fixed acceleration? No? Very well, perhaps you can do something else for me while I reconfigure the rocket...", sourceObjectiveStatus = "unverified-source-field" }
quests[14409] = { id = 14409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cautious Return", description = "A moment of your time, {class}.\n\nChange is coming. It has drawn us out of the ruins of Eldre'Thalas and into the wide world once more. I have come to research this city and cannot stray from it, but if you are inclined, I have an errand for you.\n\nMy colleague set out for Darnassus to speak with the High Priestess there, that we might come to an understanding. Take this journal to Mordent Evenshade in the temple. It may help in his diplomacy mission.", sourceObjective = "Bring Daros' Journal to Mordent Evenshade in Darnassus.", progress = "It seems I have time to talk. What is this regarding?", completion = "Ah, the writings of Daros. He always was meticulous about tracking progress. His words may aid in explaining how far we've come.\n\nYou have my thanks for bringing this to me, {race}. Perhaps we will see more of each other once it is understood we mean no harm.", sourceObjectiveStatus = "unverified-source-field" }
